-- Functions
CREATE OR REPLACE FUNCTION public.legal_activate_firm_offer_pack(_offer_id uuid, _firm_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare o jsonb; pid uuid; begin
 perform 1 from legal_firms where id=_firm_id for update;
 if not found then raise exception 'Firm not found'; end if;
 select snapshot into o from legal_firm_offers where id=_offer_id for update;
 if o is null or o->>'proposal'<>'sent' or o->>'signature'<>'executed' or o->'payments'->0->>'status'<>'paid' or not (o->>'onboardingComplete')::boolean then raise exception 'Activation requirements incomplete'; end if;
 select id into pid from legal_firm_packs where offer_id=_offer_id;
 if found then return pid; end if;
 if exists(select 1 from legal_firm_packs where firm_id=_firm_id and status='active') then raise exception 'Existing active packs require an explicit migration decision'; end if;
 insert into legal_firm_packs(firm_id,pack_size,price_per_show,price_per_show_cents,offer_id) values(_firm_id,10,((o->'draft'->>'priceCents')::numeric/100)::integer,(o->'draft'->>'priceCents')::bigint,_offer_id) returning id into pid;
 return pid;
end $function$;

CREATE OR REPLACE FUNCTION public.legal_bridge_appointment_reminder()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.kind IN ('3d','1d','24h') AND NEW.send_at IS NOT NULL THEN
    INSERT INTO legal_appointment_reminder_jobs(appointment_id,booking_version,kind,due_at,state,sent_at)
    SELECT NEW.appointment_id,booking_version,CASE WHEN NEW.kind='24h' THEN '1d' ELSE NEW.kind END,NEW.send_at,
      CASE WHEN NEW.sent_at IS NULL THEN 'pending' ELSE 'sent' END,NEW.sent_at
    FROM legal_appointment_attendance WHERE appointment_id=NEW.appointment_id ON CONFLICT DO NOTHING;
    IF NEW.sent_at IS NOT NULL THEN
      UPDATE legal_appointment_reminder_jobs SET state='sent',sent_at=NEW.sent_at
        WHERE appointment_id=NEW.appointment_id AND kind=CASE WHEN NEW.kind='24h' THEN '1d' ELSE NEW.kind END
        AND due_at=NEW.send_at AND state='pending';
    END IF;
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_can_access_portal_page(p_page text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS(SELECT 1 FROM public.legal_sales_reps r WHERE r.user_id = auth.uid() AND r.is_active
    AND (p_page = ANY(public.legal_staff_portal_pages(r.id))
      OR (r.role = 'admin' AND p_page IN ('/settings','/ad-briefing'))));
$function$;

CREATE OR REPLACE FUNCTION public.legal_can_manage_firm_pipeline()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.legal_can_access_portal_page('/firms') AND EXISTS(
    SELECT 1 FROM public.legal_sales_reps r WHERE r.user_id=auth.uid() AND r.is_active
      AND (r.role='admin' OR r.can_manage_firm_pipeline));
$function$;

CREATE OR REPLACE FUNCTION public.legal_can_view_team_clients()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.legal_sales_reps r
    WHERE r.user_id = auth.uid() AND r.is_active
      AND r.role IN ('admin', 'rep') AND r.can_view_team_clients
  );
$function$;

CREATE OR REPLACE FUNCTION public.legal_capture_appointment_office()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE office public.legal_firm_locations; active_count int; choosing boolean;
BEGIN
 choosing:=TG_OP='INSERT';
 IF TG_OP='UPDATE' THEN
   choosing:=NEW.location_id IS DISTINCT FROM OLD.location_id OR NEW.firm_id IS DISTINCT FROM OLD.firm_id;
   -- Updates to dates/outcomes keep the exact directions supplied at booking.
   IF NOT choosing THEN
     NEW.location_revision:=OLD.location_revision;
     NEW.location_name:=OLD.location_name; NEW.location_address:=OLD.location_address;
     NEW.location_parking_info:=OLD.location_parking_info; NEW.location_nearby_landmarks:=OLD.location_nearby_landmarks;
     IF NEW.consult_mode IS NOT DISTINCT FROM OLD.consult_mode THEN RETURN NEW; END IF;
   END IF;
 END IF;
 IF NEW.firm_id IS NULL THEN
   IF NEW.location_id IS NOT NULL THEN RAISE EXCEPTION 'Choose an office at the selected firm'; END IF;
   NEW.location_revision:=CASE WHEN TG_OP='INSERT' THEN 0 ELSE OLD.location_revision+1 END;
   NEW.location_name:=NULL; NEW.location_address:=NULL; NEW.location_parking_info:=NULL; NEW.location_nearby_landmarks:=NULL;
   RETURN NEW;
 END IF;
 -- Use the same firm lock as booking capacity and calendar checks.
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.firm_id::text,0));
 IF NEW.location_id IS NULL AND coalesce(NEW.consult_mode,'in_person')<>'zoom' THEN
   SELECT count(*) INTO active_count FROM public.legal_firm_locations WHERE firm_id=NEW.firm_id AND is_active;
   IF active_count<>1 THEN RAISE EXCEPTION 'Choose an office for this in-person appointment'; END IF;
   SELECT id INTO NEW.location_id FROM public.legal_firm_locations WHERE firm_id=NEW.firm_id AND is_active;
   choosing:=true;
 END IF;
 IF NEW.location_id IS NOT NULL THEN
   SELECT * INTO office FROM public.legal_firm_locations WHERE id=NEW.location_id AND firm_id=NEW.firm_id FOR SHARE;
   IF NOT FOUND OR (choosing AND NOT office.is_active) THEN RAISE EXCEPTION 'Choose an active office at the selected firm'; END IF;
   IF choosing THEN
     NEW.location_revision:=CASE WHEN TG_OP='INSERT' THEN 1 ELSE OLD.location_revision+1 END;
     NEW.location_name:=office.name;
     NEW.location_address:=nullif(concat_ws(', ',nullif(trim(office.address),''),nullif(trim(office.city),''),nullif(trim(office.state),'')),'');
     NEW.location_parking_info:=office.parking_info; NEW.location_nearby_landmarks:=office.nearby_landmarks;
   END IF;
 ELSE
   NEW.location_revision:=CASE WHEN TG_OP='INSERT' THEN 0 ELSE OLD.location_revision+1 END;
   NEW.location_name:=NULL; NEW.location_address:=NULL; NEW.location_parking_info:=NULL; NEW.location_nearby_landmarks:=NULL;
 END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_capture_legal_booking_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.booking_rep_id IS DISTINCT FROM OLD.booking_rep_id THEN RAISE EXCEPTION 'Booking ownership is immutable'; END IF;
  RETURN NEW;
 END IF;
 IF auth.uid() IS NOT NULL THEN
  SELECT id INTO NEW.booking_rep_id FROM legal_sales_reps WHERE user_id=auth.uid() AND is_active LIMIT 1;
 END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_claim_appointment_reminder(p_id uuid, p_from text, p_to text, p_settings_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE j legal_appointment_reminder_jobs; s legal_appointment_attendance; a legal_firm_appointments; cfg legal_firm_reminder_settings; start_at timestamptz; last_contact timestamptz;
BEGIN
  SELECT * INTO j FROM legal_appointment_reminder_jobs WHERE id=p_id;
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT * INTO a FROM legal_firm_appointments WHERE id=j.appointment_id FOR UPDATE;
  SELECT * INTO s FROM legal_appointment_attendance WHERE appointment_id=j.appointment_id FOR UPDATE;
  SELECT * INTO cfg FROM legal_firm_reminder_settings WHERE firm_id=a.firm_id FOR SHARE;
  SELECT * INTO j FROM legal_appointment_reminder_jobs WHERE id=p_id FOR UPDATE;
  IF j.state<>'pending' OR j.due_at>now() OR j.booking_version<>s.booking_version OR a.status<>'booked' OR a.outcome IS NOT NULL OR cfg.mode='off' OR cfg.firm_id IS NULL THEN RETURN false; END IF;
  BEGIN start_at := (a.appointment_date::text || ' ' || a.appointment_time)::timestamp AT TIME ZONE cfg.timezone;
  EXCEPTION WHEN OTHERS THEN RETURN false; END;
  IF start_at IS NULL OR start_at<=now() THEN RETURN false; END IF;
  IF p_settings_updated_at IS NOT NULL AND p_settings_updated_at<>cfg.updated_at THEN RETURN false; END IF;
  IF j.kind<>'ack' AND s.booking_changed_at>now()-interval '10 minutes' THEN RETURN false; END IF;
  IF j.kind IN ('request','followup') AND cfg.confirmation_enabled_at>now()-interval '10 minutes' THEN RETURN false; END IF;
  IF j.kind IN ('request','followup','call') AND (cfg.mode<>'confirmation' OR s.status='confirmed') THEN RETURN false; END IF;
  IF j.kind IN ('request','followup') AND s.status IN ('needs_call','review') THEN RETURN false; END IF;
  IF j.kind='ack' AND s.status<>'confirmed' THEN RETURN false; END IF;
  IF j.kind<>'call' AND (p_to IS NULL OR EXISTS(SELECT 1 FROM legal_appointment_sms_opt_outs WHERE phone=p_to)) THEN RETURN false; END IF;
  IF j.kind IN ('request','followup','3d','1d') OR (j.kind='call' AND s.status='awaiting') THEN
    SELECT max(COALESCE(sent_at,claimed_at)) INTO last_contact FROM legal_appointment_reminder_jobs
    WHERE appointment_id=j.appointment_id AND kind<>'call' AND state IN ('sending','sent','uncertain');
    IF last_contact>now()-interval '2 hours' THEN
      UPDATE legal_appointment_reminder_jobs SET due_at=last_contact+interval '2 hours' WHERE id=j.id;
      RETURN false;
    END IF;
  END IF;
  IF j.kind='call' AND s.status='awaiting' AND EXISTS(
    SELECT 1 FROM legal_appointment_reminder_jobs WHERE appointment_id=j.appointment_id AND booking_version=j.booking_version AND kind='followup' AND state='pending'
  ) THEN
    UPDATE legal_appointment_reminder_jobs SET due_at=GREATEST(now()+interval '15 minutes',
      (SELECT due_at+interval '2 hours' FROM legal_appointment_reminder_jobs WHERE appointment_id=j.appointment_id AND booking_version=j.booking_version AND kind='followup')) WHERE id=j.id;
    RETURN false;
  END IF;
  IF j.kind='followup' AND NOT EXISTS(SELECT 1 FROM legal_appointment_reminder_jobs WHERE appointment_id=j.appointment_id AND booking_version=j.booking_version AND kind='request' AND state='sent') THEN RETURN false; END IF;
  UPDATE legal_appointment_reminder_jobs SET state='sending',claimed_at=now(),from_phone=p_from,to_phone=p_to WHERE id=j.id;
  IF j.kind='request' AND s.status='unrequested' THEN UPDATE legal_appointment_attendance SET status='awaiting' WHERE appointment_id=j.appointment_id; END IF;
  IF j.kind='call' THEN UPDATE legal_appointment_attendance SET status=CASE WHEN status='review' THEN 'review' ELSE 'needs_call' END,reason=COALESCE(reason,'Attendance has not been confirmed') WHERE appointment_id=j.appointment_id; END IF;
  RETURN true;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_claim_call_hook(p_call uuid, p_hash text, p_version text, p_model text, p_user uuid, p_regenerate boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE token uuid:=gen_random_uuid(); existing legal_call_hook_insights;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service only'; END IF;
 IF p_hash !~ '^[a-f0-9]{64}$' OR NOT EXISTS(SELECT 1 FROM legal_call_records WHERE id=p_call AND lead_id IS NOT NULL) THEN RAISE EXCEPTION 'Invalid call'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('call_hook:'||p_call::text,0));
 SELECT * INTO existing FROM legal_call_hook_insights WHERE call_id=p_call FOR UPDATE;
 IF FOUND THEN
   IF existing.status='processing' AND existing.lease_until>now() THEN RETURN NULL; END IF;
   IF existing.source_hash=p_hash AND existing.status IN ('ready','unknown','excluded') AND NOT p_regenerate THEN RETURN NULL; END IF;
 END IF;
 INSERT INTO legal_call_hook_insights(call_id,source_hash,prompt_version,model,status,attempts,generation_token,lease_until,requested_by,reason)
 VALUES(p_call,p_hash,p_version,p_model,'processing',1,token,now()+interval '10 minutes',p_user,'Reviewing client conversation')
 ON CONFLICT(call_id) DO UPDATE SET source_hash=excluded.source_hash,prompt_version=excluded.prompt_version,
 model=excluded.model,status='processing',
 attempts=CASE WHEN legal_call_hook_insights.source_hash=p_hash THEN legal_call_hook_insights.attempts+1 ELSE 1 END,
 generation_token=token,lease_until=excluded.lease_until,requested_by=p_user,reason=excluded.reason,updated_at=now();
 RETURN token;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_claim_firm_pack_notifications(p_order uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE result jsonb;
BEGIN
 WITH pending AS (
   SELECT id FROM public.legal_firm_pack_orders WHERE notification_sent_at IS NULL AND notification_next_at<=now()
     AND (p_order IS NULL OR id=p_order) ORDER BY created_at LIMIT 20 FOR UPDATE SKIP LOCKED
 ), claimed AS (
   UPDATE public.legal_firm_pack_orders o SET notification_claim=gen_random_uuid(),notification_attempts=notification_attempts+1,
     notification_next_at=now()+interval '5 minutes' FROM pending WHERE o.id=pending.id RETURNING o.*
 ) SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'quantity',c.quantity,'created_at',c.created_at,
     'claim_token',c.notification_claim,'firm_name',f.firm_name)),'[]') INTO result FROM claimed c JOIN public.legal_firms f ON f.id=c.firm_id;
 RETURN result;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_claim_sales_lead(p_session_id uuid, p_previous_lead_id uuid DEFAULT NULL::uuid, p_preferred_lead_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- no_answer_four_hour_retry
DECLARE
  rep uuid := public.legal_sales_queue_rep(p_session_id);
  current_lead uuid;
  chosen uuid;
  today date := (now() AT TIME ZONE 'Australia/Sydney')::date;
BEGIN
  SELECT c.lead_id INTO current_lead FROM public.legal_sales_lead_claims c
    JOIN public.legal_client_leads l ON l.id = c.lead_id AND l.rep_id = rep
    WHERE c.session_id = p_session_id FOR UPDATE OF l;
    -- A previously reserved city may have filled up since the last request.
  IF current_lead IS NOT NULL AND NOT (SELECT public.legal_sales_queue_city_has_capacity(city) FROM public.legal_client_leads WHERE id=current_lead) THEN
    DELETE FROM public.legal_sales_lead_claims WHERE session_id=p_session_id;
    current_lead:=NULL;
  END IF;
-- A refresh resumes the current client. A repeated Next request cannot skip
  -- the client already selected by the first request.
  IF current_lead IS NOT NULL AND (
    (p_previous_lead_id IS NULL AND (p_preferred_lead_id IS NULL OR p_preferred_lead_id = current_lead))
    OR (p_previous_lead_id IS NOT NULL AND current_lead <> p_previous_lead_id)
  ) THEN
    UPDATE public.legal_sales_lead_claims SET expires_at = now() + interval '15 minutes'
      WHERE session_id = p_session_id;
    RETURN current_lead;
  END IF;

  -- Enabled callers can explicitly open a client assigned to any advisor.
  -- It still cannot take a client away from another active caller.
  IF p_preferred_lead_id IS NOT NULL THEN
    SELECT l.id INTO chosen FROM public.legal_client_leads l
    WHERE l.id = p_preferred_lead_id AND (l.rep_id = rep OR public.legal_is_admin_user() OR (l.rep_id IS NOT NULL AND public.legal_can_view_team_clients()))
      AND NOT EXISTS (SELECT 1 FROM public.legal_sales_lead_claims c
        JOIN public.legal_rep_sessions s ON s.id = c.session_id
        WHERE c.lead_id = l.id AND c.session_id <> p_session_id
          AND c.expires_at > now() AND s.ended_at IS NULL)
    FOR UPDATE OF l SKIP LOCKED;
    IF chosen IS NULL THEN RAISE EXCEPTION 'This client is unavailable or with another caller'; END IF;
    IF NOT (SELECT public.legal_sales_queue_city_has_capacity(city) FROM public.legal_client_leads WHERE id=chosen) THEN
      RAISE EXCEPTION 'Sydney calls are paused: no booking capacity is available.';
    END IF;
  END IF;

  IF current_lead IS NOT NULL THEN
    INSERT INTO public.legal_sales_session_visits(session_id, lead_id, visited_at)
      VALUES (p_session_id, current_lead, now())
      ON CONFLICT (session_id, lead_id) DO UPDATE SET visited_at = excluded.visited_at;
  END IF;
  DELETE FROM public.legal_sales_lead_claims WHERE session_id = p_session_id;

  IF p_preferred_lead_id IS NULL THEN
    SELECT l.id INTO chosen FROM public.legal_client_leads l
    LEFT JOIN LATERAL (
      SELECT count(DISTINCT coalesce(c.twilio_call_sid, c.id::text)) FILTER (
          WHERE (c.created_at AT TIME ZONE 'Australia/Sydney')::date = today) AS attempts_today,
        count(DISTINCT (c.created_at AT TIME ZONE 'Australia/Sydney')::date) AS call_days,
        (array_agg(lower(coalesce(c.call_status, '')) ORDER BY c.created_at DESC, c.id))[1] AS last_status
      FROM public.legal_call_records c WHERE c.lead_id = l.id
        AND (c.direction IS NULL OR c.direction = 'outbound')
        AND lower(coalesce(c.call_status, '')) NOT IN ('failed','canceled','cancelled','initiated','skipped')
    ) a ON true
    -- A call made before this queue/session existed still counts as worked today.
    -- Include initiated/failed/cancelled dials: moving on must not recycle them
    -- merely because a final telephony status has not arrived. Explicit redials
    -- on the current client remain available.
    LEFT JOIN LATERAL (
      SELECT max(c.created_at) AS last_dial_today
      FROM public.legal_call_records c WHERE c.lead_id = l.id
        AND (c.direction IS NULL OR c.direction = 'outbound')
        AND lower(coalesce(c.call_status, '')) <> 'skipped'
        AND (c.created_at AT TIME ZONE 'Australia/Sydney')::date = today
    ) worked ON true
    WHERE public.legal_sales_queue_city_has_capacity(l.city) AND NOT (l.status = 'callback_scheduled' AND l.callback_scheduled_at IS NOT NULL AND l.callback_scheduled_at > now())
      AND (
        lower(regexp_replace(trim(coalesce(l.first_name,'') || ' ' || coalesce(l.last_name,'')), '\s+', ' ', 'g')) IN ('peter test','peter test 2')
        OR (
          l.status NOT IN ('not_interested','booked_deposit_paid','had_convo_no_sale','did_not_qualify','cancelled','no_show','dropped')
          AND NOT EXISTS (SELECT 1 FROM public.legal_app_settings s,
            LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(s.value) = 'array' THEN s.value ELSE '[]'::jsonb END) AS cities(city_name)
            WHERE s.key = 'paused_cities' AND lower(trim(cities.city_name)) = lower(trim(l.city)))
          AND NOT EXISTS (SELECT 1 FROM public.legal_app_settings s
            WHERE s.key = 'focus_cities' AND jsonb_typeof(s.value) = 'array' AND s.value <> '[]'::jsonb
              AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements_text(s.value) AS cities(city_name) WHERE lower(trim(cities.city_name)) = lower(trim(l.city))))
          AND (
            worked.last_dial_today IS NULL OR (l.status = 'no_answer' AND worked.last_dial_today <= now() - interval '4 hours')
            OR (l.status = 'callback_scheduled' AND l.callback_scheduled_at > worked.last_dial_today
              AND l.callback_scheduled_at <= now())
            OR EXISTS (SELECT 1 FROM public.legal_call_records c WHERE c.lead_id = l.id
              AND c.direction = 'inbound' AND c.created_at > worked.last_dial_today)
          )
          AND ((l.status = 'no_answer' AND worked.last_dial_today <= now() - interval '4 hours') OR a.attempts_today < CASE WHEN (l.created_at AT TIME ZONE 'Australia/Sydney')::date >= today - 6 THEN 3 ELSE 1 END)
          AND NOT (a.call_days > 21 AND (l.status = 'no_answer' OR a.last_status IN ('no-answer','no_answer','noanswer','busy','voicemail','missed')))
        )
      )
      AND NOT EXISTS (SELECT 1 FROM public.legal_sales_lead_claims c
        JOIN public.legal_rep_sessions s ON s.id = c.session_id
        WHERE c.lead_id = l.id AND c.expires_at > now() AND s.ended_at IS NULL)
      AND NOT EXISTS (SELECT 1 FROM public.legal_sales_session_visits v
        WHERE v.session_id = p_session_id AND v.lead_id = l.id AND NOT (coalesce((l.status = 'no_answer' AND worked.last_dial_today <= now() - interval '4 hours'), false) AND v.visited_at <= now() - interval '4 hours')
          AND NOT (l.status = 'callback_scheduled' AND l.callback_scheduled_at IS NOT NULL AND l.callback_scheduled_at > v.visited_at AND l.callback_scheduled_at <= now())
          AND NOT EXISTS (SELECT 1 FROM public.legal_call_records c WHERE c.lead_id = l.id
            AND c.direction = 'inbound' AND c.created_at > v.visited_at))
    ORDER BY CASE WHEN (l.status = 'no_answer' AND worked.last_dial_today <= now() - interval '4 hours') THEN 1 ELSE 0 END, CASE WHEN (l.status = 'no_answer' AND worked.last_dial_today <= now() - interval '4 hours') THEN worked.last_dial_today END, l.created_at DESC, l.id
    LIMIT 1 FOR UPDATE OF l SKIP LOCKED;
  END IF;

  IF chosen IS NULL THEN RETURN NULL; END IF;
  -- All claim/renew paths lock the lead first, so expired reservations can be
  -- reclaimed without racing another caller's renewal.
  DELETE FROM public.legal_sales_lead_claims WHERE lead_id = chosen;
  INSERT INTO public.legal_sales_lead_claims(lead_id, session_id, expires_at)
    VALUES (chosen, p_session_id, now() + interval '15 minutes');
  UPDATE public.legal_client_leads SET rep_id = rep WHERE id = chosen;
  RETURN chosen;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_current_firm_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT firm_id FROM public.legal_firm_portal_users WHERE id = auth.uid() LIMIT 1;
$function$;

CREATE OR REPLACE FUNCTION public.legal_current_portal_access()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'canManageFirmPipeline', public.legal_can_manage_firm_pipeline(),
    'isStaff', public.legal_has_sales_role(), 'isAdmin', public.legal_is_admin_user(),
    'isSetter', EXISTS(SELECT 1 FROM public.legal_sales_reps r, public.legal_app_settings s
      WHERE r.user_id = auth.uid() AND r.is_active AND r.role <> 'admin' AND s.key = 'cold_calling'
      AND coalesce(s.value->'setter_user_ids','[]'::jsonb) ? r.user_id::text),
    'salesOnly', public.legal_is_sales_only_user(), 'firmId', public.legal_current_firm_id(),
    'pages', coalesce((SELECT to_jsonb(public.legal_staff_portal_pages(r.id)) FROM public.legal_sales_reps r
      WHERE r.user_id = auth.uid() AND r.is_active LIMIT 1), '[]'::jsonb));
$function$;

CREATE OR REPLACE FUNCTION public.legal_current_sales_rep_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT r.id FROM public.legal_sales_reps r WHERE r.user_id = auth.uid() AND r.is_active LIMIT 1;
$function$;

CREATE OR REPLACE FUNCTION public.legal_enforce_admin_only_disqualification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF public.legal_is_service_or_admin() THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.outcome = 'disqualified' OR NEW.disqualified_reason IS NOT NULL
       OR NEW.disqualified_at IS NOT NULL OR NEW.disqualified_by IS NOT NULL THEN
      RAISE EXCEPTION 'Only Legal Group staff can disqualify an appointment';
    END IF;
    RETURN NEW;
  END IF;
  IF (NEW.outcome = 'disqualified' AND COALESCE(OLD.outcome,'') <> 'disqualified')
     OR NEW.disqualified_reason IS DISTINCT FROM OLD.disqualified_reason
     OR NEW.disqualified_at IS DISTINCT FROM OLD.disqualified_at
     OR NEW.disqualified_by IS DISTINCT FROM OLD.disqualified_by THEN
    RAISE EXCEPTION 'Only Legal Group staff can disqualify an appointment';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.legal_enforce_firm_appointment_update_limits()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF public.legal_is_service_or_admin() THEN RETURN NEW; END IF;
  IF NEW.refund_status IS DISTINCT FROM OLD.refund_status
     OR NEW.refund_processed_at IS DISTINCT FROM OLD.refund_processed_at
     OR NEW.stripe_refund_id IS DISTINCT FROM OLD.stripe_refund_id
     OR NEW.intel_notes IS DISTINCT FROM OLD.intel_notes
     OR NEW.client_name IS DISTINCT FROM OLD.client_name
     OR NEW.client_phone IS DISTINCT FROM OLD.client_phone
     OR NEW.client_email IS DISTINCT FROM OLD.client_email
     OR NEW.ex_partner_name IS DISTINCT FROM OLD.ex_partner_name
     OR NEW.firm_id IS DISTINCT FROM OLD.firm_id
     OR NEW.lead_id IS DISTINCT FROM OLD.lead_id
     OR NEW.lawyer_id IS DISTINCT FROM OLD.lawyer_id
     OR NEW.chase_result_at IS DISTINCT FROM OLD.chase_result_at
     OR NEW.chase_result_by IS DISTINCT FROM OLD.chase_result_by
     OR NEW.status IS DISTINCT FROM OLD.status
     OR NEW.conflict_resolved_at IS DISTINCT FROM OLD.conflict_resolved_at THEN
    RAISE EXCEPTION 'This field can only be changed by Legal Group';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.legal_finish_firm_pack_notification(p_order uuid, p_claim uuid, p_sent boolean)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 UPDATE public.legal_firm_pack_orders SET notification_sent_at=CASE WHEN p_sent THEN now() ELSE NULL END,
   notification_next_at=now()+interval '15 minutes',notification_claim=NULL
 WHERE id=p_order AND notification_claim=p_claim AND notification_sent_at IS NULL;
$function$;

CREATE OR REPLACE FUNCTION public.legal_firm_name_key(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$ SELECT NULLIF(regexp_replace(regexp_replace(regexp_replace(lower(coalesce(p, '')), '&', ' and ', 'g'), '\m(pty\.?\s*ltd\.?|pty\.?\s*limited|proprietary\s+limited|limited|ltd\.?|inc\.?|llp|llc|the|and)\M', ' ', 'g'), '[^a-z0-9]', '', 'g'), '') $function$;

CREATE OR REPLACE FUNCTION public.legal_firm_offer_rate_limit(_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer; begin
 insert into legal_firm_offer_rate_limits(key) values (_key) on conflict(key) do update set
 count=case when legal_firm_offer_rate_limits.window_start < now()-interval '1 minute' then 1 else legal_firm_offer_rate_limits.count+1 end,
 window_start=case when legal_firm_offer_rate_limits.window_start < now()-interval '1 minute' then now() else legal_firm_offer_rate_limits.window_start end returning count into n;
 return n<=30;
end $function$;

CREATE OR REPLACE FUNCTION public.legal_firm_offer_show_milestone()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare oid uuid; count_shows integer; begin
 if NEW.offer_pack_id is null then return NEW; end if;
 select offer_id into oid from legal_firm_packs where id=NEW.offer_pack_id for update;
 if not exists(select 1 from legal_firm_offers where id=oid and snapshot->'draft'->>'arrangement'='split') then return NEW; end if;
 select count(*) into count_shows from legal_firm_appointments where offer_pack_id=NEW.offer_pack_id and status<>'cancelled' and outcome in ('show','signed') and coalesce(client_name,'') not ilike '%test%';
 if count_shows>=5 then insert into legal_firm_offer_milestones(offer_id) values(oid) on conflict do nothing; end if;
 if count_shows<5 then update legal_firm_offer_milestones set review_required=true where offer_id=oid; end if;
 return NEW;
end $function$;

CREATE OR REPLACE FUNCTION public.legal_firm_phone_key(value text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$ SELECT CASE WHEN regexp_replace(coalesce(value,''),'[^0-9]','','g') ~ '^(61[23478][0-9]{8}|0[23478][0-9]{8}|[23478][0-9]{8})$' THEN '+61'||right(regexp_replace(value,'[^0-9]','','g'),9) END; $function$;

CREATE OR REPLACE FUNCTION public.legal_firm_schedule_snapshot(p_firm uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 SELECT jsonb_build_object(
  'firm_id',c.id,'firm_name',c.firm_name,'state',c.state,
  'consultation_minutes',c.consultation_duration_minutes,'buffer_minutes',c.buffer_minutes,
  'trading',coalesce((SELECT jsonb_agg(to_jsonb(t)||jsonb_build_object('is_closed',NOT t.is_open) ORDER BY t.day_of_week) FROM public.legal_firm_trading_hours t WHERE t.firm_id=c.id),'[]'),
  'blocks',coalesce((SELECT jsonb_agg(to_jsonb(b) ORDER BY b.id) FROM public.legal_firm_blocked_slots b WHERE b.firm_id=c.id),'[]'),
  'overrides',coalesce((SELECT jsonb_agg(to_jsonb(o) ORDER BY o.override_date) FROM public.legal_firm_availability o WHERE o.firm_id=c.id),'[]'),
  'appointments',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'client_name',CASE WHEN public.legal_is_admin_user() OR public.legal_current_firm_id()=c.id THEN a.client_name ELSE NULL END,'appointment_date',a.appointment_date,'appointment_time',a.appointment_time,'consultation_duration_minutes',a.consultation_duration_minutes) ORDER BY a.id) FROM public.legal_firm_appointments a WHERE a.status<>'cancelled' AND a.disqualified_at IS NULL AND a.outcome IS DISTINCT FROM 'disqualified' AND a.firm_id=c.id),'[]')
 ) FROM public.legal_firms c WHERE c.id=p_firm
$function$;

CREATE OR REPLACE FUNCTION public.legal_freeze_firm_offer_pack_terms()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
 if OLD.offer_id is not null and (NEW.offer_id is distinct from OLD.offer_id or NEW.firm_id is distinct from OLD.firm_id or NEW.pack_size is distinct from OLD.pack_size or NEW.price_per_show is distinct from OLD.price_per_show or NEW.price_per_show_cents is distinct from OLD.price_per_show_cents) then raise exception 'Signed offer pack terms are immutable'; end if;
 return NEW;
end $function$;

CREATE OR REPLACE FUNCTION public.legal_freeze_firm_offer_payment_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare old_payment jsonb; new_payment jsonb; field text; begin
 for old_payment in select value from jsonb_array_elements(coalesce(OLD.snapshot->'payments','[]'::jsonb)) loop
  select value into new_payment from jsonb_array_elements(coalesce(NEW.snapshot->'payments','[]'::jsonb)) where value->>'id'=old_payment->>'id';
  if new_payment is null then raise exception 'Payment requests cannot be removed; cancel and reconcile explicitly'; end if;
  foreach field in array array['id','block','paymentProvider','amountCents','dueDate'] loop
   if new_payment->field is distinct from old_payment->field then raise exception 'Payment request identity and terms are immutable'; end if;
  end loop;
  foreach field in array array['invoiceId','orderId','customerId'] loop
   if old_payment->field is not null and new_payment->field is distinct from old_payment->field then raise exception 'Provider references are immutable'; end if;
  end loop;
 end loop;
 return NEW;
end $function$;

CREATE OR REPLACE FUNCTION public.legal_gate_firm_offer_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p public.legal_firm_packs; consumes boolean; already_reserved boolean:=false;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.firm_id::text,0));
 IF TG_OP='UPDATE' AND OLD.offer_pack_id IS NOT NULL
   AND (NEW.firm_id IS DISTINCT FROM OLD.firm_id OR NEW.offer_pack_id IS DISTINCT FROM OLD.offer_pack_id) THEN
   RAISE EXCEPTION 'Offer reservation cannot be reassigned';
 END IF;
 IF TG_OP='UPDATE' AND OLD.offer_pack_id IS NULL AND NEW.offer_pack_id IS NOT NULL THEN
   RAISE EXCEPTION 'Legacy appointments require an explicit migration decision';
 END IF;
 consumes:=NEW.status NOT IN ('cancelled','no_show') AND NEW.disqualified_at IS NULL
   AND (NEW.outcome IS NULL OR NEW.outcome IN ('show','signed'))
   AND (NEW.firm_id='7102a000-7729-4141-965c-8ba2d946d3e5' OR coalesce(NEW.client_name,'') NOT ILIKE '%test%');
 IF NOT consumes THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' THEN
   already_reserved:=OLD.firm_id=NEW.firm_id AND OLD.status NOT IN ('cancelled','no_show') AND OLD.disqualified_at IS NULL
     AND (OLD.outcome IS NULL OR OLD.outcome IN ('show','signed'))
     AND (OLD.firm_id='7102a000-7729-4141-965c-8ba2d946d3e5' OR coalesce(OLD.client_name,'') NOT ILIKE '%test%');
 END IF;
 IF already_reserved THEN RETURN NEW; END IF;
 -- Existing legacy advance bookings remain editable; only new reservations
 -- must have capacity. The firm lock prevents concurrent overbooking.
 IF public.legal_get_firm_pack_balance(NEW.firm_id)<=0 THEN RAISE EXCEPTION 'No open pack capacity for this firm, or bookings are on hold'; END IF;
 IF TG_OP='INSERT' THEN
   SELECT * INTO p FROM public.legal_firm_packs WHERE firm_id=NEW.firm_id AND offer_id IS NOT NULL AND status='active' ORDER BY purchased_at,id LIMIT 1;
   NEW.offer_pack_id:=p.id;
 END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_get_firm_calendar_history(p_firm uuid, p_before bigint DEFAULT NULL::bigint, p_date date DEFAULT NULL::date, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE result jsonb;
BEGIN
 IF NOT(coalesce(auth.role(),'')='service_role' OR coalesce(legal_current_firm_id()=p_firm,false) OR coalesce(legal_is_admin_user(),false)) THEN RAISE EXCEPTION 'You do not have access to this calendar history'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id::bigint DESC),'[]') INTO result FROM (
 SELECT id::text,entity_type,entity_id,operation,recorded_at,actor_name,actor_role,before_data,after_data FROM legal_firm_calendar_history h
 WHERE firm_id=p_firm AND (p_before IS NULL OR h.id<p_before) AND (p_date IS NULL OR entity_type IN ('weekly_hours','settings') OR before_data->>'date'=p_date::text OR after_data->>'date'=p_date::text OR before_data->>'appointment_date'=p_date::text OR after_data->>'appointment_date'=p_date::text OR before_data->>'override_date'=p_date::text OR after_data->>'override_date'=p_date::text OR (after_data->>'is_recurring')::boolean IS TRUE OR (before_data->>'is_recurring')::boolean IS TRUE)
 ORDER BY h.id DESC LIMIT least(100,greatest(1,p_limit))+1) page;
 RETURN jsonb_build_object('started_at',(SELECT min(recorded_at) FROM legal_firm_calendar_history WHERE firm_id=p_firm),'entries',result);
END $function$;

CREATE OR REPLACE FUNCTION public.legal_get_firm_pack_balance(_firm_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p public.legal_firm_packs; o jsonb; capacity integer:=0; used integer;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' AND NOT coalesce(public.legal_is_admin_user(),false)
    AND public.legal_current_firm_id() IS DISTINCT FROM _firm_id
    AND NOT coalesce(public.legal_can_access_portal_page('/sales-call'),false)
    AND NOT coalesce(public.legal_can_access_portal_page('/booked-appointments'),false)
    AND NOT coalesce(public.legal_can_access_portal_page('/firm-portal'),false) THEN
   RAISE EXCEPTION 'You cannot view this firm balance';
 END IF;
 FOR p IN SELECT * FROM public.legal_firm_packs WHERE firm_id=_firm_id AND status IN ('active','completed') LOOP
   IF p.on_hold AND p.status='active' THEN RETURN 0; END IF;
   IF p.offer_id IS NULL THEN capacity:=capacity+p.pack_size;
   ELSE
     SELECT snapshot INTO o FROM public.legal_firm_offers WHERE id=p.offer_id;
     IF o->>'signature' IS DISTINCT FROM 'executed' OR NOT coalesce((o->>'onboardingComplete')::boolean,false)
       OR o->'payments'->0->>'status' IS DISTINCT FROM 'paid' THEN RETURN 0; END IF;
     capacity:=capacity+CASE WHEN o->'draft'->>'arrangement'='split' AND o->'payments'->1->>'status' IS DISTINCT FROM 'paid' THEN 5 ELSE p.pack_size END;
   END IF;
 END LOOP;
 SELECT count(*) INTO used FROM public.legal_firm_appointments a WHERE a.firm_id=_firm_id
   AND a.status NOT IN ('cancelled','no_show') AND a.disqualified_at IS NULL
   AND (a.outcome IS NULL OR a.outcome IN ('show','signed'))
   AND (_firm_id='7102a000-7729-4141-965c-8ba2d946d3e5' OR coalesce(a.client_name,'') NOT ILIKE '%test%');
 RETURN capacity-used;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_get_firm_schedule(p_firm uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE result jsonb;
BEGIN
 IF NOT (coalesce(auth.role(),'')='service_role' OR coalesce(public.legal_current_firm_id()=p_firm,false) OR coalesce((public.legal_can_access_portal_page('/firm-portal') OR public.legal_can_access_portal_page('/sales-call') OR public.legal_can_access_portal_page('/booked-appointments')),false)) THEN RAISE EXCEPTION 'You do not have access to this calendar'; END IF;
 result:=public.legal_firm_schedule_snapshot(p_firm);
 IF result IS NULL THEN RAISE EXCEPTION 'Firm not found'; END IF;
 RETURN result||jsonb_build_object('version',md5(result::text));
END $function$;

CREATE OR REPLACE FUNCTION public.legal_guard_booking_slot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c public.legal_firms; h record; starts integer; finishes integer; gap integer;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.firm_id::text,0));
 SELECT * INTO c FROM public.legal_firms WHERE id=NEW.firm_id;
 IF c.id IS NULL THEN RAISE EXCEPTION 'Firm not found'; END IF;
 IF TG_OP='INSERT' THEN NEW.consultation_duration_minutes:=c.consultation_duration_minutes;
 ELSIF NEW.firm_id IS DISTINCT FROM OLD.firm_id THEN NEW.consultation_duration_minutes:=c.consultation_duration_minutes;
 ELSIF NEW.consultation_duration_minutes IS DISTINCT FROM OLD.consultation_duration_minutes AND NOT (coalesce(current_setting('app.confirmed_duration_firm',true),'')=NEW.firm_id::text AND NEW.consultation_duration_minutes=c.consultation_duration_minutes AND NEW.appointment_date=OLD.appointment_date AND NEW.appointment_time=OLD.appointment_time AND NEW.firm_id=OLD.firm_id) THEN
   RAISE EXCEPTION 'An existing appointment keeps its booked consultation length';
 END IF;
 IF NEW.status='cancelled' OR NEW.disqualified_at IS NOT NULL OR NEW.outcome='disqualified' OR NEW.appointment_date IS NULL OR NEW.appointment_time IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND OLD.status<>'cancelled' AND OLD.disqualified_at IS NULL AND OLD.outcome IS DISTINCT FROM 'disqualified' AND NEW.appointment_date=OLD.appointment_date AND NEW.appointment_time::time=OLD.appointment_time::time AND NEW.firm_id=OLD.firm_id THEN RETURN NEW; END IF;
 IF NEW.appointment_date < (now() AT TIME ZONE 'Australia/Sydney')::date OR
   (NEW.appointment_date=(now() AT TIME ZONE 'Australia/Sydney')::date AND NEW.appointment_time::time <= (now() AT TIME ZONE 'Australia/Sydney')::time)
 THEN RAISE EXCEPTION 'Choose a future appointment time'; END IF;
 SELECT * INTO h FROM public.legal_schedule_hours(NEW.firm_id,NEW.appointment_date);
 starts:=public.legal_schedule_minute(NEW.appointment_time); finishes:=starts+NEW.consultation_duration_minutes; gap:=c.buffer_minutes;
 IF h.opens IS NULL OR h.step<1 OR starts<h.opens OR finishes>h.closes THEN
   RAISE EXCEPTION 'That appointment does not fit within working hours. Choose another time.';
 END IF;
 IF EXISTS(SELECT 1 FROM public.legal_firm_blocked_slots b WHERE b.firm_id=NEW.firm_id AND public.legal_schedule_block_matches(b,NEW.appointment_date)
   AND starts<coalesce(public.legal_schedule_minute(b.end_time::text),1440) AND finishes>coalesce(public.legal_schedule_minute(b.start_time::text),0)) THEN
   RAISE EXCEPTION 'That appointment would run into blocked time. Choose another time.';
 END IF;
 IF EXISTS(SELECT 1 FROM public.legal_firm_appointments a WHERE a.status<>'cancelled' AND a.disqualified_at IS NULL AND a.outcome IS DISTINCT FROM 'disqualified' AND a.firm_id=NEW.firm_id AND a.id<>NEW.id AND a.appointment_date=NEW.appointment_date
   AND public.legal_schedule_minute(a.appointment_time)<finishes+gap
   AND public.legal_schedule_minute(a.appointment_time)+a.consultation_duration_minutes+gap>starts) THEN
   RAISE EXCEPTION 'That time was just taken or overlaps another appointment or buffer. Choose another time.';
 END IF;
 RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_guard_firm_offer_invitation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
 if NEW.snapshot->>'proposal'='sent' and OLD.snapshot->>'proposal'<>'sent' then
  perform pg_advisory_xact_lock(hashtextextended(NEW.application_id::text,0));
  if exists(select 1 from legal_firm_offers where application_id=NEW.application_id and id<>NEW.id and snapshot->>'proposal'='sent') then raise exception 'Withdraw the previous unsigned offer before sending a revision'; end if;
 end if;
 return NEW;
end $function$;

