CREATE OR REPLACE FUNCTION public.legal_is_service_or_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE claim_role text;
DECLARE active_role text;
BEGIN
  BEGIN
    claim_role := coalesce(current_setting('request.jwt.claims', true)::json->>'role', '');
  EXCEPTION WHEN others THEN claim_role := '';
  END;
  IF claim_role = 'service_role' THEN RETURN true; END IF;

  -- NOTE: current_user is the function owner inside SECURITY DEFINER, so it must
  -- never be used for caller identity. current_setting('role') reflects the role
  -- PostgREST switched to for this request; session_user covers direct psql use.
  BEGIN
    active_role := coalesce(current_setting('role', true), '');
  EXCEPTION WHEN others THEN active_role := '';
  END;
  IF active_role IN ('service_role', 'postgres', 'supabase_admin') THEN RETURN true; END IF;
  IF active_role IN ('none', '') AND session_user IN ('postgres', 'supabase_admin') THEN RETURN true; END IF;

  RETURN public.legal_is_admin_user();
END;
$function$;

CREATE OR REPLACE FUNCTION public.legal_legal_calendar_history_fields(kind text, r jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE keys text[]; result jsonb;
BEGIN
 IF r IS NULL THEN RETURN NULL; END IF;
 keys:=CASE kind WHEN 'block' THEN ARRAY['date','start_time','end_time','is_recurring','recur_pattern','recur_day_of_week','recur_days_of_week','recur_day_of_month','recur_nth_week','recur_until','excluded_dates']
 WHEN 'hours' THEN ARRAY['override_date','override_type','start_time','end_time']
 WHEN 'weekly_hours' THEN ARRAY['day_of_week','open_time','close_time','is_open','slot_times','consult_duration_mins']
 WHEN 'settings' THEN ARRAY['consultation_duration_minutes','buffer_minutes']
 ELSE ARRAY['appointment_date','appointment_time','consultation_duration_minutes','status','outcome','disqualified_at'] END;
 SELECT jsonb_object_agg(key,value) INTO result FROM jsonb_each(r) WHERE key=ANY(keys);
 IF kind='weekly_hours' THEN result:=result||jsonb_build_object('is_closed',NOT (r->>'is_open')::boolean); END IF;
 IF kind='appointment' THEN result:=result||jsonb_build_object('calendar_status',CASE WHEN r->>'disqualified_at' IS NOT NULL OR r->>'outcome'='disqualified' THEN 'disqualified' WHEN r->>'status'='cancelled' THEN 'cancelled' ELSE 'booked' END); END IF;
 RETURN result;
END $function$;

