 RETURNS TABLE(id uuid, user_id uuid, name text, email text, role text, is_active boolean, pages text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.legal_is_admin_user() THEN RAISE EXCEPTION 'Admins only'; END IF;
  RETURN QUERY SELECT r.id, r.user_id, r.name, r.email, r.role, r.is_active, public.legal_staff_portal_pages(r.id)
    FROM public.legal_sales_reps r ORDER BY r.name NULLS LAST, r.id;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_lock_legal_schedule_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE fid uuid;
BEGIN
 IF TG_TABLE_NAME='legal_firms' THEN fid:=NEW.id;
 ELSE
  fid:=CASE WHEN TG_OP='DELETE' THEN OLD.firm_id ELSE NEW.firm_id END;
  IF TG_OP='UPDATE' AND NEW.firm_id IS DISTINCT FROM OLD.firm_id THEN RAISE EXCEPTION 'Calendar rows cannot move between firms'; END IF;
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(fid::text,0));
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_match_firm_application(p_phone text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ SELECT CASE WHEN count(*)=1 THEN (array_agg(id))[1] END FROM public.legal_firm_applications WHERE public.legal_firm_phone_key(phone)=public.legal_firm_phone_key(p_phone); $function$;

CREATE OR REPLACE FUNCTION public.legal_mirror_firm_sms()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE app_id uuid; BEGIN app_id:=public.legal_match_firm_application(NEW.phone); IF app_id IS NOT NULL AND length(coalesce(NEW.body,''))>=1 THEN
IF TG_OP='UPDATE' THEN PERFORM public.legal_update_firm_sms_status(NULL,NEW.twilio_sid,NEW.delivery_status,NULL); RETURN NEW; END IF;
INSERT INTO public.legal_firm_application_messages(application_id,direction,phone,body,status,twilio_sid,source_sms_id,created_at,reviewed_at) VALUES(app_id,NEW.direction,public.legal_firm_phone_key(NEW.phone),NEW.body,coalesce(NEW.delivery_status,'unknown'),NEW.twilio_sid,NEW.id,NEW.created_at,CASE WHEN TG_OP='INSERT' THEN NULL ELSE now() END) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $function$;

CREATE OR REPLACE FUNCTION public.legal_normalize_phone(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT right(regexp_replace(coalesce(p,''), '\D', '', 'g'), 9);
$function$;

CREATE OR REPLACE FUNCTION public.legal_order_firm_pack(p_firm uuid, p_request uuid, p_quantity integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE existing public.legal_firm_pack_orders; prior public.legal_firm_packs; oid uuid; pid uuid; rate bigint; o jsonb;
BEGIN
 IF auth.uid() IS NULL OR public.legal_current_firm_id() IS DISTINCT FROM p_firm THEN
   RAISE EXCEPTION 'Only a member of this firm can order a pack';
 END IF;
 IF p_request IS NULL OR p_quantity IS NULL OR p_quantity NOT BETWEEN 1 AND 100 THEN
   RAISE EXCEPTION 'Choose between 1 and 100 credits';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_firm::text,0));
 SELECT * INTO existing FROM public.legal_firm_pack_orders WHERE firm_id=p_firm AND request_id=p_request;
 IF FOUND THEN
   IF existing.quantity<>p_quantity OR existing.requested_by<>auth.uid() THEN
     RAISE EXCEPTION 'This confirmation has already been used. Refresh your credits.';
   END IF;
   RETURN jsonb_build_object('id',existing.id,'pack_id',existing.pack_id,'quantity',existing.quantity,'payment_status',existing.payment_status);
 END IF;
 IF EXISTS(SELECT 1 FROM public.legal_firm_packs WHERE firm_id=p_firm AND status='active' AND on_hold) THEN
   RAISE EXCEPTION 'Your bookings are on hold. Contact Bold before adding a pack.';
 END IF;
 -- Additional credits must not bypass outstanding initial agreement obligations.
 FOR o IN SELECT f.snapshot FROM public.legal_firm_packs p JOIN public.legal_firm_offers f ON f.id=p.offer_id
   WHERE p.firm_id=p_firm AND p.status IN ('active','completed') LOOP
   IF o->>'signature' IS DISTINCT FROM 'executed' OR coalesce((o->>'onboardingComplete')::boolean,false)=false
      OR coalesce(jsonb_array_length(o->'payments'),0)=0
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(o->'payments') payment WHERE payment->>'status' IS DISTINCT FROM 'paid') THEN
     RAISE EXCEPTION 'Please contact Bold to complete your existing agreement or payment before adding a pack.';
   END IF;
 END LOOP;
 SELECT * INTO prior FROM public.legal_firm_packs WHERE firm_id=p_firm AND status IN ('active','completed')
   ORDER BY purchased_at DESC,created_at DESC,id DESC LIMIT 1;
 rate:=coalesce(prior.price_per_show_cents,prior.price_per_show::bigint*100);
 IF prior.id IS NULL OR rate IS NULL OR rate<=0 THEN
   RAISE EXCEPTION 'Contact Bold to set up your first pack and agreed rate.';
 END IF;
 INSERT INTO public.legal_firm_packs(firm_id,pack_size,price_per_show,price_per_show_cents,status,on_hold)
   VALUES(p_firm,p_quantity,round(rate::numeric/100)::integer,rate,'active',false) RETURNING id INTO pid;
 INSERT INTO public.legal_firm_pack_orders(firm_id,request_id,requested_by,pack_id,quantity,price_per_show_cents)
   VALUES(p_firm,p_request,auth.uid(),pid,p_quantity,rate) RETURNING id INTO oid;
 RETURN jsonb_build_object('id',oid,'pack_id',pid,'quantity',p_quantity,'payment_status','manual_pending');
END $function$;

CREATE OR REPLACE FUNCTION public.legal_portal_auth_users_export(p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$ DECLARE result jsonb; BEGIN IF NOT coalesce(public.legal_is_admin_user(), false) THEN RAISE EXCEPTION 'Admins only' USING ERRCODE = '42501'; END IF; SELECT coalesce(jsonb_agg(jsonb_build_object( 'id', u.id, 'email', u.email, 'phone', u.phone, 'user_metadata', u.raw_user_meta_data, 'created_at', u.created_at, 'last_sign_in_at', u.last_sign_in_at, 'email_confirmed_at', u.email_confirmed_at, 'banned_until', u.banned_until ) ORDER BY u.created_at, u.id), '[]'::jsonb) INTO result FROM (SELECT * FROM auth.users ORDER BY created_at, id OFFSET greatest(coalesce(p_offset, 0), 0) LIMIT 1000) u; RETURN result; END; $function$;

CREATE OR REPLACE FUNCTION public.legal_portal_leaderboard_source(p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE result jsonb; BEGIN IF NOT ( public.legal_is_admin_user() OR EXISTS ( SELECT 1 FROM public.legal_sales_reps r WHERE r.user_id = auth.uid() AND r.is_active AND r.role IN ('admin', 'rep') ) ) THEN RAISE EXCEPTION 'Staff only' USING ERRCODE = '42501'; END IF; IF p_from IS NULL OR p_to IS NULL OR p_to < p_from OR p_to - p_from > interval '400 days' THEN RAISE EXCEPTION 'Invalid range' USING ERRCODE = '22023'; END IF; WITH calls AS ( SELECT c.id, c.rep_id, c.lead_id, c.direction, c.call_status, c.duration_seconds, c.created_at FROM public.legal_call_records c WHERE c.created_at >= p_from AND c.created_at <= p_to AND coalesce(c.direction, 'outbound') <> 'inbound' ), appts AS ( SELECT a.id, a.lead_id, a.status, a.created_at FROM public.legal_firm_appointments a WHERE a.status <> 'cancelled' AND a.created_at >= p_from AND a.created_at <= p_to ), deposits AS ( SELECT l.id, l.rep_id, l.deposit_paid_at FROM public.legal_client_leads l WHERE l.deposit_paid_at >= p_from AND l.deposit_paid_at <= p_to ), lead_ids AS ( SELECT lead_id AS id FROM calls WHERE lead_id IS NOT NULL UNION SELECT lead_id FROM appts WHERE lead_id IS NOT NULL UNION SELECT id FROM deposits ) SELECT jsonb_build_object( 'reps', (SELECT coalesce(jsonb_agg(to_jsonb(r)), '[]'::jsonb) FROM ( SELECT id, name, email, role, is_active, created_at FROM public.legal_sales_reps WHERE is_active ) r), 'calls', (SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.created_at), '[]'::jsonb) FROM calls c), 'appts', (SELECT coalesce(jsonb_agg(to_jsonb(a)), '[]'::jsonb) FROM appts a), 'deposits', (SELECT coalesce(jsonb_agg(to_jsonb(d)), '[]'::jsonb) FROM deposits d), 'leads', (SELECT coalesce(jsonb_agg(to_jsonb(l)), '[]'::jsonb) FROM ( SELECT cl.id, cl.rep_id, cl.first_name, cl.last_name FROM public.legal_client_leads cl JOIN lead_ids i ON i.id = cl.id ) l) ) INTO result; RETURN result; END; $function$;

CREATE OR REPLACE FUNCTION public.legal_portal_schema_export()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$ DECLARE result jsonb; BEGIN IF NOT coalesce(public.legal_is_admin_user(), false) THEN RAISE EXCEPTION 'Admins only' USING ERRCODE = '42501'; END IF; SELECT jsonb_build_object( 'tables', ( SELECT coalesce(jsonb_agg(jsonb_build_object( 'name', c.relname, 'kind', c.relkind, 'rls', c.relrowsecurity, 'force_rls', c.relforcerowsecurity, 'acl', c.relacl::text[], 'columns', ( SELECT coalesce(jsonb_agg(jsonb_build_object( 'name', a.attname, 'type', format_type(a.atttypid, a.atttypmod), 'not_null', a.attnotnull, 'default', pg_get_expr(d.adbin, d.adrelid), 'identity', a.attidentity, 'generated', a.attgenerated ) ORDER BY a.attnum), '[]'::jsonb) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped ) ) ORDER BY c.relname), '[]'::jsonb) FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r', 'p') ), 'constraints', ( SELECT coalesce(jsonb_agg(jsonb_build_object( 'table', c.conrelid::regclass::text, 'name', c.conname, 'type', c.contype, 'def', pg_get_constraintdef(c.oid) ) ORDER BY c.conrelid::regclass::text, c.contype, c.conname), '[]'::jsonb) FROM pg_constraint c WHERE c.connamespace = 'public'::regnamespace AND c.conrelid <> 0 ), 'indexes', ( SELECT coalesce(jsonb_agg(jsonb_build_object( 'table', i.tablename, 'name', i.indexname, 'def', i.indexdef ) ORDER BY i.tablename, i.indexname), '[]'::jsonb) FROM pg_indexes i WHERE i.schemaname = 'public' AND NOT EXISTS (SELECT 1 FROM pg_constraint k WHERE k.conname = i.indexname AND k.connamespace = 'public'::regnamespace) ), 'views', ( SELECT coalesce(jsonb_agg(jsonb_build_object( 'name', c.relname, 'kind', c.relkind, 'def', pg_get_viewdef(c.oid, true), 'options', c.reloptions, 'acl', c.relacl::text[] ) ORDER BY c.relname), '[]'::jsonb) FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('v', 'm') ), 'sequences', ( SELECT coalesce(jsonb_agg(c.relname ORDER BY c.relname), '[]'::jsonb) FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relkind = 'S' ), 'types', ( SELECT coalesce(jsonb_agg(jsonb_build_object( 'name', t.typname, 'kind', t.typtype, 'labels', (SELECT jsonb_agg(e.enumlabel ORDER BY e.enumsortorder) FROM pg_enum e WHERE e.enumtypid = t.oid), 'domain_type', CASE WHEN t.typtype = 'd' THEN format_type(t.typbasetype, t.typtypmod) END ) ORDER BY t.typname), '[]'::jsonb) FROM pg_type t WHERE t.typnamespace = 'public'::regnamespace AND t.typtype IN ('e', 'd') ), 'functions', ( SELECT coalesce(jsonb_agg(jsonb_build_object( 'name', p.proname, 'args', pg_get_function_identity_arguments(p.oid), 'kind', p.prokind, 'def', pg_get_functiondef(p.oid), 'acl', p.proacl::text[] ) ORDER BY p.proname, pg_get_function_identity_arguments(p.oid)), '[]'::jsonb) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.prokind IN ('f', 'p') AND NOT EXISTS (SELECT 1 FROM pg_depend dep WHERE dep.objid = p.oid AND dep.deptype = 'e') ), 'triggers', ( SELECT coalesce(jsonb_agg(jsonb_build_object( 'table', t.tgrelid::regclass::text, 'name', t.tgname, 'def', pg_get_triggerdef(t.oid), 'enabled', t.tgenabled ) ORDER BY t.tgrelid::regclass::text, t.tgname), '[]'::jsonb) FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid WHERE NOT t.tgisinternal AND c.relnamespace IN ('public'::regnamespace, 'auth'::regnamespace) ), 'policies', ( SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.schemaname, p.tablename, p.policyname), '[]'::jsonb) FROM pg_policies p WHERE p.schemaname IN ('public', 'storage') ), 'buckets', ( SELECT coalesce(jsonb_agg(jsonb_build_object( 'id', b.id, 'name', b.name, 'public', b.public, 'file_size_limit', b.file_size_limit, 'allowed_mime_types', b.allowed_mime_types ) ORDER BY b.id), '[]'::jsonb) FROM storage.buckets b ), 'cron', ( SELECT coalesce(jsonb_agg(jsonb_build_object( 'name', j.jobname, 'schedule', j.schedule, 'command', j.command, 'active', j.active ) ORDER BY j.jobname), '[]'::jsonb) FROM cron.job j ), 'row_counts', ( SELECT coalesce(jsonb_object_agg(s.relname, s.n_live_tup), '{}'::jsonb) FROM pg_stat_user_tables s WHERE s.schemaname = 'public' ), 'storage_objects', ( SELECT coalesce(jsonb_object_agg(o.bucket_id, o.n), '{}'::jsonb) FROM (SELECT bucket_id, count(*) AS n FROM storage.objects GROUP BY bucket_id) o ), 'auth_users', (SELECT count(*) FROM auth.users) ) INTO result; RETURN result; END; $function$;

CREATE OR REPLACE FUNCTION public.legal_portal_table_export(p_table text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 1000)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$ DECLARE rel oid; order_by text; result jsonb; BEGIN IF NOT coalesce(public.legal_is_admin_user(), false) THEN RAISE EXCEPTION 'Admins only' USING ERRCODE = '42501'; END IF; SELECT c.oid INTO rel FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r', 'p') AND c.relname = p_table; IF rel IS NULL THEN RAISE EXCEPTION 'Unknown table %', p_table USING ERRCODE = '22023'; END IF; SELECT string_agg(quote_ident(a.attname), ', ' ORDER BY array_position(i.indkey::int2[], a.attnum)) INTO order_by FROM pg_index i JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY (i.indkey) WHERE i.indrelid = rel AND i.indisprimary; EXECUTE format( 'SELECT coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) FROM (SELECT * FROM public.%I ORDER BY %s OFFSET %s LIMIT %s) t', p_table, coalesce(order_by, 'ctid'), greatest(coalesce(p_offset, 0), 0), least(greatest(coalesce(p_limit, 1000), 1), 1000) ) INTO result; RETURN result; END; $function$;

CREATE OR REPLACE FUNCTION public.legal_prospect_apply_dnc()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.do_not_contact AND (TG_OP = 'INSERT' OR NOT OLD.do_not_contact) THEN
    IF NEW.phone_e164 IS NOT NULL THEN
      INSERT INTO public.legal_phone_suppressions (phone_e164, phone_tail, prospect_firm_id, reason, source, created_by)
      VALUES (NEW.phone_e164, public.legal_normalize_phone(NEW.phone_e164), CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE NEW.id END,
              coalesce(NEW.do_not_contact_reason, 'Do Not Contact'), 'prospect_dnc', NEW.do_not_contact_by)
      ON CONFLICT (phone_e164) DO NOTHING;
    END IF;
    NEW.next_follow_up_at := NULL;
    NEW.prospect_status := 'do_not_contact';
    IF NEW.do_not_contact_at IS NULL THEN NEW.do_not_contact_at := now(); END IF;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.legal_prospect_guard_call_attempt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE f public.legal_prospect_firms%ROWTYPE;
BEGIN
  SELECT * INTO f FROM public.legal_prospect_firms WHERE id = NEW.prospect_firm_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Prospect not found'; END IF;
  IF f.do_not_contact THEN RAISE EXCEPTION 'Prospect is marked Do Not Contact'; END IF;
  IF public.legal_is_phone_suppressed(NEW.to_number) OR public.legal_is_phone_suppressed(f.phone_e164) THEN
    RAISE EXCEPTION 'Number is on the global suppression list';
  END IF;
  IF NEW.to_number IS DISTINCT FROM f.phone_e164 THEN
    RAISE EXCEPTION 'Dial number does not match the firm''s public business number';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.legal_protect_booked_time()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE firm uuid; day date; a public.legal_firm_appointments; b public.legal_firm_blocked_slots; h record; starts integer; finishes integer;
BEGIN
 firm:=CASE WHEN TG_OP='DELETE' THEN OLD.firm_id ELSE NEW.firm_id END;
 IF TG_TABLE_NAME='legal_firm_trading_hours' AND coalesce(current_setting('app.confirmed_hours_firm',true),'')=firm::text THEN RETURN NULL; END IF;
 IF TG_TABLE_NAME='legal_firm_blocked_slots' THEN
   IF TG_OP='DELETE' THEN RETURN NULL; END IF;
   SELECT * INTO b FROM public.legal_firm_blocked_slots WHERE id=NEW.id;
   IF NOT FOUND THEN RETURN NULL; END IF;
   FOR a IN SELECT * FROM public.legal_firm_appointments WHERE status<>'cancelled' AND disqualified_at IS NULL AND outcome IS DISTINCT FROM 'disqualified' AND firm_id=firm AND appointment_date >= (now() AT TIME ZONE 'Australia/Sydney')::date LOOP
     IF public.legal_schedule_block_matches(b,a.appointment_date) AND public.legal_schedule_minute(a.appointment_time)<coalesce(public.legal_schedule_minute(b.end_time::text),1440)
       AND public.legal_schedule_minute(a.appointment_time)+a.consultation_duration_minutes>coalesce(public.legal_schedule_minute(b.start_time::text),0)
     THEN RAISE EXCEPTION 'A client is already booked on % at %. Keep their appointment free.',a.appointment_date,a.appointment_time; END IF;
   END LOOP;
 ELSE
   FOR a IN SELECT * FROM public.legal_firm_appointments WHERE status<>'cancelled' AND disqualified_at IS NULL AND outcome IS DISTINCT FROM 'disqualified' AND firm_id=firm AND appointment_date >= (now() AT TIME ZONE 'Australia/Sydney')::date LOOP
     IF TG_TABLE_NAME='legal_firm_availability' THEN
       day:=CASE WHEN TG_OP='DELETE' THEN OLD.override_date ELSE NEW.override_date END;
       IF a.appointment_date<>day THEN CONTINUE; END IF;
     ELSE
       IF extract(dow FROM a.appointment_date)::integer<>(CASE WHEN TG_OP='DELETE' THEN OLD.day_of_week ELSE NEW.day_of_week END) THEN CONTINUE; END IF;
     END IF;
     SELECT * INTO h FROM public.legal_schedule_hours(firm,a.appointment_date);
     starts:=public.legal_schedule_minute(a.appointment_time); finishes:=starts+a.consultation_duration_minutes;
     IF h.opens IS NULL OR starts<h.opens OR finishes>h.closes THEN
       RAISE EXCEPTION 'A client is already booked on % at %. Keep their full appointment within working hours.',a.appointment_date,a.appointment_time;
     END IF;
   END LOOP;
 END IF;
 RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_rebook_client_after_no_show(p_lead uuid, p_previous uuid, p_actor uuid, p_firm uuid, p_lawyer uuid, p_date date, p_time text, p_mode text, p_reminders jsonb, p_location uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  l public.legal_client_leads; a public.legal_firm_appointments; existing public.legal_firm_appointments;
  rep public.legal_sales_reps; new_id uuid; normalized_time text; t time;
BEGIN
  IF p_firm IS NULL OR p_date IS NULL OR p_time IS NULL OR p_mode IS NULL
     OR p_mode NOT IN ('in_person','zoom') OR p_reminders IS NULL
     OR jsonb_typeof(p_reminders)<>'array' THEN RAISE EXCEPTION 'Choose a firm, date and time'; END IF;
  -- Same lock order as rescheduling and the capacity/calendar triggers.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_firm::text,0));
  SELECT * INTO l FROM public.legal_client_leads WHERE id=p_lead FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Client not found'; END IF;
  SELECT * INTO rep FROM public.legal_sales_reps WHERE user_id=p_actor AND is_active;
  IF rep.id IS NULL OR NOT coalesce('/sales-call'=ANY(public.legal_staff_portal_pages(rep.id))
     OR '/booked-appointments'=ANY(public.legal_staff_portal_pages(rep.id))
     OR '/leads'=ANY(public.legal_staff_portal_pages(rep.id))
     OR '/inbox'=ANY(public.legal_staff_portal_pages(rep.id)),false)
     OR (rep.role<>'admin' AND l.rep_id IS DISTINCT FROM rep.id) THEN
    RAISE EXCEPTION 'You cannot act on this client';
  END IF;
  SELECT * INTO a FROM public.legal_firm_appointments WHERE id=p_previous AND lead_id=p_lead FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Previous appointment not found'; END IF;
  IF p_location IS NULL AND p_mode<>'zoom' AND
    (SELECT count(*) FROM public.legal_firm_locations WHERE firm_id=p_firm AND is_active)=1 THEN
    SELECT id INTO p_location FROM public.legal_firm_locations WHERE firm_id=p_firm AND is_active;
  END IF;
  t:=p_time::time;
  normalized_time:=lower(to_char(t,'FMHH12:MIam'));
  SELECT * INTO existing FROM public.legal_firm_appointments WHERE rebooked_from=a.id;
  IF FOUND THEN
    IF existing.location_id IS NOT DISTINCT FROM p_location AND existing.firm_id=p_firm AND existing.lawyer_id IS NOT DISTINCT FROM p_lawyer
       AND existing.appointment_date=p_date AND existing.appointment_time::time=t
       AND existing.consult_mode=p_mode AND existing.status='booked' AND existing.outcome IS NULL
       AND existing.disqualified_at IS NULL THEN
      RETURN jsonb_build_object('appointmentId',existing.id,'alreadyBooked',true);
    END IF;
    RAISE EXCEPTION 'This client has already been rebooked. Refresh to see their appointment.';
  END IF;
  IF a.status='cancelled' OR a.disqualified_at IS NOT NULL
     OR NOT (a.outcome IS NOT DISTINCT FROM 'noshow' OR (a.status='no_show' AND a.outcome IS NULL)) THEN
    RAISE EXCEPTION 'Only a missed appointment can be rebooked here. Refresh the client.';
  END IF;
  IF EXISTS(SELECT 1 FROM public.legal_firm_appointments x WHERE x.lead_id=p_lead
      AND x.id<>a.id AND (x.created_at>a.created_at OR
        (x.status='booked' AND x.outcome IS NULL AND x.disqualified_at IS NULL))) THEN
    RAISE EXCEPTION 'This client has another appointment. Refresh before booking.';
  END IF;
  IF p_date<(now() AT TIME ZONE 'Australia/Sydney')::date OR
     (p_date=(now() AT TIME ZONE 'Australia/Sydney')::date AND t<=(now() AT TIME ZONE 'Australia/Sydney')::time) THEN
    RAISE EXCEPTION 'Choose a future appointment time';
  END IF;
  IF l.deposit_paid_at IS NULL THEN RAISE EXCEPTION 'The client payment needs to be checked before booking'; END IF;
  IF a.refund_status IN ('refunded','pending','processing','manual','failed') THEN
    RAISE EXCEPTION 'The previous payment has a refund recorded. Ask an administrator to check it before rebooking.';
  END IF;
  IF nullif(trim(l.ex_partner_full_name),'') IS NULL THEN
    RAISE EXCEPTION 'Save the other side''s full name before booking';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.legal_firms WHERE id=p_firm AND is_active) THEN
    RAISE EXCEPTION 'Choose an active firm';
  END IF;
  IF p_lawyer IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.legal_firm_lawyers WHERE id=p_lawyer AND firm_id=p_firm AND is_active) THEN
    RAISE EXCEPTION 'Choose a lawyer at the selected firm';
  END IF;
  -- Existing insert triggers enforce live availability and pack capacity.
  INSERT INTO public.legal_firm_appointments(lead_id,booking_rep_id,firm_id,lawyer_id,
    appointment_date,appointment_time,consult_mode,status,conflict_status,
    client_name,client_phone,client_email,ex_partner_name,intel_notes,rebooked_from,location_id)
  VALUES(l.id,rep.id,p_firm,p_lawyer,p_date,normalized_time,p_mode,'booked','pending',
    nullif(trim(concat_ws(' ',l.first_name,l.last_name)),''),l.phone,l.email,
    l.ex_partner_full_name,a.intel_notes,a.id,p_location) RETURNING id INTO new_id;
  UPDATE public.legal_client_leads SET booking_date=p_date,booking_time=normalized_time,
    firm_id=p_firm,lawyer_id=p_lawyer,handover_sent_at=NULL WHERE id=l.id;
  UPDATE public.legal_firm_appointments SET chase_status='rebooked',chase_result_at=now() WHERE id=a.id;
  INSERT INTO public.legal_firm_appointment_notes(appointment_id,firm_id,author_type,author_name,body) VALUES
    (a.id,a.firm_id,'admin',rep.name,format('Client rebooked for %s at %s. Original no-show retained.',p_date,normalized_time)),
    (new_id,p_firm,'admin',rep.name,format('Rebooked after missed appointment on %s at %s.',a.appointment_date,a.appointment_time));
  INSERT INTO public.legal_appointment_reminders(appointment_id,send_at,kind)
    SELECT new_id,(r->>'send_at')::timestamptz,r->>'kind' FROM jsonb_array_elements(p_reminders) r;
  RETURN jsonb_build_object('appointmentId',new_id,'alreadyBooked',false);
END $function$;

CREATE OR REPLACE FUNCTION public.legal_record_appointment_call(p_appointment_id uuid, p_version uuid, p_outcome text, p_actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s legal_appointment_attendance; a legal_firm_appointments;
BEGIN
  IF p_outcome NOT IN ('confirmed','no_answer','voicemail') THEN RAISE EXCEPTION 'Invalid call outcome'; END IF;
  SELECT * INTO a FROM legal_firm_appointments WHERE id=p_appointment_id FOR UPDATE;
  SELECT * INTO s FROM legal_appointment_attendance WHERE appointment_id=p_appointment_id FOR UPDATE;
  IF s.booking_version IS DISTINCT FROM p_version OR a.status<>'booked' OR a.outcome IS NOT NULL THEN RAISE EXCEPTION 'Appointment changed. Refresh before recording the outcome.'; END IF;
  UPDATE legal_appointment_attendance SET call_outcome=p_outcome,called_at=now(),
    status=CASE WHEN p_outcome='confirmed' THEN 'confirmed' WHEN status='confirmed' THEN status ELSE 'needs_call' END,
    confirmed_at=CASE WHEN p_outcome='confirmed' THEN now() ELSE confirmed_at END,
    reason=CASE WHEN p_outcome='confirmed' THEN NULL ELSE reason END WHERE appointment_id=p_appointment_id;
  INSERT INTO legal_appointment_attendance_events(appointment_id,booking_version,kind,detail,actor_id) VALUES(p_appointment_id,p_version,'call',p_outcome,p_actor);
  IF p_outcome='confirmed' THEN UPDATE legal_appointment_reminder_jobs SET state='cancelled',last_error='Confirmed by phone' WHERE appointment_id=p_appointment_id AND booking_version=p_version AND kind IN ('request','followup','call') AND state='pending'; END IF;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_record_appointment_delivery(p_id uuid, p_sid text, p_status text, p_error text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE j legal_appointment_reminder_jobs; s legal_appointment_attendance; a legal_firm_appointments; cfg legal_firm_reminder_settings; old_rank integer; new_rank integer;
BEGIN
  SELECT * INTO j FROM legal_appointment_reminder_jobs WHERE (p_id IS NOT NULL AND id=p_id) OR (p_id IS NULL AND twilio_sid=p_sid);
  IF NOT FOUND THEN RETURN; END IF;
  SELECT * INTO a FROM legal_firm_appointments WHERE id=j.appointment_id FOR UPDATE;
  SELECT * INTO s FROM legal_appointment_attendance WHERE appointment_id=j.appointment_id FOR UPDATE;
  SELECT * INTO j FROM legal_appointment_reminder_jobs WHERE id=j.id FOR UPDATE;
  IF j.twilio_sid IS NOT NULL AND j.twilio_sid<>p_sid THEN RETURN; END IF;
  old_rank := COALESCE(array_position(ARRAY['accepted','queued','sending','sent','failed','undelivered','delivered','read'],j.delivery_status),0);
  new_rank := COALESCE(array_position(ARRAY['accepted','queued','sending','sent','failed','undelivered','delivered','read'],p_status),0);
  IF new_rank<=old_rank THEN RETURN; END IF;
  UPDATE legal_appointment_reminder_jobs SET twilio_sid=p_sid,delivery_status=p_status,
    state=CASE WHEN p_status IN ('failed','undelivered') THEN 'failed' WHEN p_status IN ('delivered','read') THEN 'sent' ELSE state END,
    sent_at=CASE WHEN p_status IN ('delivered','read') THEN COALESCE(sent_at,now()) ELSE sent_at END,
    last_error=CASE WHEN p_status IN ('failed','undelivered') THEN 'SMS '||p_status||COALESCE(' ('||p_error||')','') WHEN p_status IN ('delivered','read') THEN NULL ELSE last_error END WHERE id=j.id;
  SELECT * INTO cfg FROM legal_firm_reminder_settings WHERE firm_id=a.firm_id;
  IF p_status IN ('failed','undelivered') AND j.kind<>'ack' AND cfg.mode='confirmation' THEN
    UPDATE legal_appointment_attendance SET status='needs_call',reason='Reminder text could not be delivered'
      WHERE appointment_id=j.appointment_id AND booking_version=j.booking_version AND status IN ('unrequested','awaiting','needs_call');
  END IF;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_record_appointment_reply(p_sid text, p_from text, p_to text, p_body text, p_opt_out text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE candidate record; matches integer; latest_request timestamptz; safe_yes boolean; is_stop boolean; is_start boolean; current_status text;
BEGIN
  IF p_sid='' OR p_from IS NULL THEN RETURN; END IF;
  INSERT INTO legal_appointment_sms_receipts(sid) VALUES(p_sid) ON CONFLICT DO NOTHING;
  IF NOT FOUND THEN RETURN; END IF;
  is_stop := upper(COALESCE(p_opt_out,''))='STOP' OR upper(trim(p_body)) IN ('STOP','STOPALL','UNSUBSCRIBE','CANCEL','END','QUIT','REVOKE','OPTOUT');
  is_start := upper(COALESCE(p_opt_out,''))='START' OR upper(trim(p_body)) IN ('START','UNSTOP');
  IF is_stop THEN INSERT INTO legal_appointment_sms_opt_outs(phone) VALUES(p_from) ON CONFLICT DO NOTHING; END IF;
  IF is_start THEN DELETE FROM legal_appointment_sms_opt_outs WHERE phone=p_from; END IF;
  SELECT count(DISTINCT (appointment_id,booking_version)),max(COALESCE(sent_at,claimed_at)) INTO matches,latest_request
    FROM legal_appointment_reminder_jobs WHERE to_phone=p_from AND from_phone=p_to AND kind IN ('request','followup')
    AND state IN ('sent','sending','uncertain') AND claimed_at>now()-interval '7 days';
  FOR candidate IN
    SELECT DISTINCT s.appointment_id,s.booking_version,a.lead_id,cfg.mode FROM legal_appointment_attendance s
    JOIN legal_firm_appointments a ON a.id=s.appointment_id JOIN legal_firm_reminder_settings cfg ON cfg.firm_id=a.firm_id
    WHERE a.status='booked' AND a.outcome IS NULL AND a.appointment_date >= (now() AT TIME ZONE cfg.timezone)::date
    AND (EXISTS(SELECT 1 FROM legal_appointment_reminder_jobs j WHERE j.appointment_id=a.id AND j.to_phone=p_from AND j.from_phone=p_to AND j.kind IN ('request','followup') AND j.claimed_at>now()-interval '7 days')
      OR (is_stop AND right(regexp_replace(COALESCE(a.client_phone,(SELECT phone FROM legal_client_leads WHERE id=a.lead_id)), '[^0-9]', '', 'g'),9)=right(p_from,9)))
    ORDER BY s.appointment_id
  LOOP
    PERFORM 1 FROM legal_firm_appointments WHERE id=candidate.appointment_id FOR UPDATE;
    SELECT status INTO current_status FROM legal_appointment_attendance WHERE appointment_id=candidate.appointment_id AND booking_version=candidate.booking_version FOR UPDATE;
    IF NOT FOUND THEN CONTINUE; END IF;
    safe_yes := NOT is_stop AND NOT is_start AND upper(trim(p_body)) IN ('YES','Y') AND matches=1
      AND EXISTS(SELECT 1 FROM legal_appointment_reminder_jobs WHERE appointment_id=candidate.appointment_id AND booking_version=candidate.booking_version AND to_phone=p_from AND from_phone=p_to AND kind IN ('request','followup') AND state='sent' AND sent_at>now()-interval '7 days')
      AND NOT EXISTS(SELECT 1 FROM legal_sms_messages m WHERE m.direction='outbound' AND right(regexp_replace(m.phone,'[^0-9]','','g'),9)=right(p_from,9) AND m.created_at>latest_request
        AND NOT EXISTS(SELECT 1 FROM legal_appointment_reminder_jobs j WHERE j.twilio_sid=m.twilio_sid AND j.appointment_id=candidate.appointment_id AND j.booking_version=candidate.booking_version));
    UPDATE legal_appointment_attendance SET latest_reply=left(p_body,4000),latest_reply_at=now(),
      status=CASE WHEN safe_yes THEN 'confirmed' WHEN is_stop AND current_status='confirmed' THEN 'confirmed' WHEN is_start THEN status ELSE 'review' END,
      confirmed_at=CASE WHEN safe_yes THEN now() ELSE confirmed_at END,
      reason=CASE WHEN safe_yes THEN NULL WHEN is_stop THEN 'Client opted out of reminder texts' WHEN is_start THEN reason ELSE 'Reply needs human review; no booking changes made' END
      WHERE appointment_id=candidate.appointment_id AND booking_version=candidate.booking_version;
    INSERT INTO legal_appointment_attendance_events(appointment_id,booking_version,kind,detail) VALUES(candidate.appointment_id,candidate.booking_version,'reply',left(p_body,4000));
    IF safe_yes THEN
      UPDATE legal_appointment_reminder_jobs SET state='cancelled',last_error='Client confirmed attendance' WHERE appointment_id=candidate.appointment_id AND booking_version=candidate.booking_version AND kind IN ('request','followup','call') AND state='pending';
      IF current_status<>'confirmed' THEN
        INSERT INTO legal_appointment_reminder_jobs(appointment_id,booking_version,kind,due_at) VALUES(candidate.appointment_id,candidate.booking_version,'ack',now()) ON CONFLICT DO NOTHING;
      END IF;
    END IF;
  END LOOP;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_record_legal_calendar_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE kind text; old_data jsonb; new_data jsonb; old_raw jsonb; new_raw jsonb; fid uuid; eid uuid; actor text; actor_role text;
BEGIN
 kind:=CASE TG_TABLE_NAME WHEN 'legal_firms' THEN 'settings' WHEN 'legal_firm_appointments' THEN 'appointment' WHEN 'legal_firm_trading_hours' THEN 'weekly_hours' WHEN 'legal_firm_availability' THEN 'hours' ELSE 'block' END;
 IF TG_OP<>'INSERT' THEN old_raw:=to_jsonb(OLD);old_data:=legal_legal_calendar_history_fields(kind,old_raw); END IF;
 IF TG_OP<>'DELETE' THEN new_raw:=to_jsonb(NEW);new_data:=legal_legal_calendar_history_fields(kind,new_raw); END IF;
 IF old_data IS NOT DISTINCT FROM new_data THEN RETURN NULL; END IF;
 fid:=CASE WHEN kind='settings' THEN (coalesce(new_raw,old_raw)->>'id')::uuid ELSE (coalesce(new_raw,old_raw)->>'firm_id')::uuid END;
 eid:=(coalesce(new_raw,old_raw)->>'id')::uuid;IF fid IS NULL THEN RETURN NULL; END IF;
 SELECT name,role INTO actor,actor_role FROM legal_sales_reps WHERE user_id=auth.uid() LIMIT 1;
 INSERT INTO legal_firm_calendar_history(firm_id,entity_type,entity_id,operation,actor_name,actor_role,before_data,after_data)
 VALUES(fid,kind,eid,CASE TG_OP WHEN 'INSERT' THEN 'added' WHEN 'DELETE' THEN 'removed' ELSE 'changed' END,coalesce(actor,CASE WHEN legal_current_firm_id()=fid THEN 'Firm user' ELSE 'System' END),coalesce(actor_role,'firm'),old_data,new_data);
 RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_release_sales_session_claim()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.ended_at IS NOT NULL THEN
    DELETE FROM public.legal_sales_lead_claims WHERE session_id = NEW.id;
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_renew_sales_lead(p_session_id uuid, p_lead_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE rep uuid := public.legal_sales_queue_rep(p_session_id); lead_city text;
BEGIN
 SELECT city INTO lead_city FROM public.legal_client_leads WHERE id=p_lead_id AND rep_id=rep FOR UPDATE;
 IF NOT FOUND THEN RETURN false; END IF;
 IF NOT public.legal_sales_queue_city_has_capacity(lead_city) THEN RETURN false; END IF;
 UPDATE public.legal_sales_lead_claims SET expires_at=now()+interval '15 minutes'
   WHERE session_id=p_session_id AND lead_id=p_lead_id;
 RETURN FOUND;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_replace_legal_meta_spend(p_from date, p_to date, p_account text, p_campaigns text[], p_rows jsonb, p_account_name text, p_total numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service only'; END IF;
 IF p_from IS NULL OR p_to IS NULL OR p_to<p_from OR p_to-p_from>366 OR coalesce(cardinality(p_campaigns),0)<1 OR p_account IS NULL OR jsonb_typeof(p_rows) IS DISTINCT FROM 'array' OR p_total IS NULL OR p_total<0 THEN RAISE EXCEPTION 'Invalid sync'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('legal_meta_spend',0));
 IF EXISTS(SELECT 1 FROM jsonb_to_recordset(p_rows) AS r(date date,ad_id text,campaign_id text,spend_aud numeric) WHERE r.date IS NULL OR r.date NOT BETWEEN p_from AND p_to OR r.ad_id IS NULL OR r.campaign_id IS NULL OR NOT(r.campaign_id=ANY(p_campaigns)) OR r.spend_aud IS NULL OR r.spend_aud<0) THEN RAISE EXCEPTION 'Invalid Meta row'; END IF;
 IF abs(coalesce((SELECT sum(r.spend_aud) FROM jsonb_to_recordset(p_rows) AS r(spend_aud numeric)),0)-p_total)>0.02 THEN RAISE EXCEPTION 'Meta totals do not reconcile'; END IF;
 IF EXISTS(SELECT 1 FROM legal_ad_spend_sync_state WHERE id=1 AND account_id IS NOT NULL AND (account_id<>p_account OR campaign_ids IS DISTINCT FROM p_campaigns)) THEN RAISE EXCEPTION 'Reporting account or campaigns changed. Review historic coverage before switching.'; END IF;
 DELETE FROM legal_ad_spend_daily WHERE source='meta' AND account_id=p_account AND date BETWEEN p_from AND p_to AND campaign_id=ANY(p_campaigns);
 INSERT INTO legal_ad_spend_daily(date,ad_id,ad_name,adset_name,campaign_id,campaign_name,account_id,location,spend_aud,impressions,clicks,source)
 SELECT r.date,r.ad_id,r.ad_name,r.adset_name,r.campaign_id,r.campaign_name,p_account,r.location,r.spend_aud,r.impressions,r.clicks,'meta'
 FROM jsonb_to_recordset(p_rows) AS r(date date,ad_id text,ad_name text,adset_name text,campaign_id text,campaign_name text,location text,spend_aud numeric,impressions bigint,clicks bigint);
 INSERT INTO legal_ad_spend_coverage(date,synced_at,account_id,campaign_ids) SELECT d::date,now(),p_account,p_campaigns FROM generate_series(p_from,p_to,'1 day'::interval)d ON CONFLICT(date) DO UPDATE SET synced_at=excluded.synced_at,account_id=excluded.account_id,campaign_ids=excluded.campaign_ids;
 UPDATE legal_ad_spend_sync_state SET last_synced_at=now(),last_attempt_at=now(),last_status='ok',last_message='Verified against campaign-level Meta totals',account_id=p_account,account_name=p_account_name,currency='AUD',timezone='Australia/Sydney',coverage_from=(SELECT min(date) FROM legal_ad_spend_coverage),coverage_to=(SELECT max(date) FROM legal_ad_spend_coverage),campaign_ids=p_campaigns,ad_total=p_total,reference_total=p_total WHERE id=1;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_replace_legal_meta_spend_with_metrics(p_from date, p_to date, p_account text, p_campaigns text[], p_rows jsonb, p_account_name text, p_total numeric, p_fetched_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service only'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('legal_meta_spend',0));
 IF p_fetched_at IS NULL OR p_fetched_at>now()+interval '5 minutes' OR p_fetched_at<now()-interval '26 hours' THEN RAISE EXCEPTION 'Invalid source snapshot'; END IF;
 IF EXISTS(SELECT 1 FROM legal_ad_spend_sync_state WHERE id=1 AND last_synced_at>p_fetched_at) THEN RAISE EXCEPTION 'A newer source snapshot has already been imported'; END IF;
 IF EXISTS (
   SELECT 1 FROM jsonb_array_elements(p_rows) r,
     LATERAL jsonb_each(CASE WHEN jsonb_typeof(r->'video_metrics')='object' THEN r->'video_metrics' ELSE '{}'::jsonb END) m
   WHERE jsonb_typeof(m.value) NOT IN ('number','null') OR (jsonb_typeof(m.value)='number' AND (m.value::text)::numeric<0)
 ) THEN RAISE EXCEPTION 'Invalid video metric'; END IF;
 PERFORM legal_replace_legal_meta_spend(p_from,p_to,p_account,p_campaigns,p_rows,p_account_name,p_total);
 UPDATE legal_ad_spend_daily d SET creative_id=r.creative_id,adset_id=r.adset_id,
   video_metrics=r.video_metrics,metrics_fetched_at=r.metrics_fetched_at
 FROM jsonb_to_recordset(p_rows) r(date date,ad_id text,creative_id text,adset_id text,video_metrics jsonb,metrics_fetched_at timestamptz)
 WHERE d.source='meta' AND d.account_id=p_account AND d.ad_id=r.ad_id AND d.date=r.date;
 UPDATE legal_ad_spend_sync_state SET last_synced_at=p_fetched_at WHERE id=1;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_reschedule_firm_appointment(p_appointment uuid, p_date date, p_time text, p_expected_date date, p_expected_time text, p_author text, p_reminders jsonb, p_location uuid DEFAULT NULL::uuid, p_change_location boolean DEFAULT false, p_expected_location uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE a public.legal_firm_appointments; fid uuid;
BEGIN
 SELECT firm_id INTO fid FROM public.legal_firm_appointments WHERE id=p_appointment;
 PERFORM pg_advisory_xact_lock(hashtextextended(fid::text,0));
 SELECT * INTO a FROM public.legal_firm_appointments WHERE id=p_appointment FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Appointment not found'; END IF;
 IF a.status='cancelled' OR a.outcome IS NOT NULL OR a.disqualified_at IS NOT NULL THEN
   RAISE EXCEPTION 'Only an upcoming appointment can be rescheduled';
 END IF;
 IF a.appointment_date IS DISTINCT FROM p_expected_date OR a.appointment_time IS DISTINCT FROM p_expected_time THEN
   RAISE EXCEPTION 'This appointment has changed. Refresh and choose a time again.';
 END IF;
 IF p_change_location AND a.location_id IS DISTINCT FROM p_expected_location THEN
   RAISE EXCEPTION 'This appointment office has changed. Refresh before saving.';
 END IF;
 IF p_author NOT IN ('admin','firm') OR jsonb_typeof(p_reminders)<>'array' THEN
   RAISE EXCEPTION 'Invalid reschedule details';
 END IF;
 -- Existing slot guard enforces actual booked duration, buffers and hours.
 UPDATE public.legal_firm_appointments SET appointment_date=p_date,appointment_time=p_time,
   location_id=CASE WHEN p_change_location THEN p_location ELSE a.location_id END WHERE id=a.id;
 IF a.lead_id IS NOT NULL THEN
   UPDATE public.legal_client_leads SET booking_date=p_date,booking_time=p_time WHERE id=a.lead_id;
   IF NOT FOUND THEN RAISE EXCEPTION 'Client record missing; no changes saved'; END IF;
 END IF;
 INSERT INTO public.legal_firm_appointment_notes(appointment_id,firm_id,author_type,body)
   VALUES(a.id,a.firm_id,p_author,format('Rescheduled from %s %s → %s %s',a.appointment_date,a.appointment_time,p_date,p_time) || CASE WHEN p_change_location AND a.location_id IS DISTINCT FROM p_location THEN format(' · Office changed from %s to %s',a.location_name,(SELECT location_name FROM legal_firm_appointments WHERE id=a.id)) ELSE '' END);
 DELETE FROM public.legal_appointment_reminders WHERE appointment_id=a.id AND sent_at IS NULL;
 INSERT INTO public.legal_appointment_reminders(appointment_id,send_at,kind)
   SELECT a.id,(r->>'send_at')::timestamptz,r->>'kind' FROM jsonb_array_elements(p_reminders) r;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_sales_booking_times(p_firm_id uuid)
 RETURNS TABLE(appointment_date date, appointment_time text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT a.appointment_date, a.appointment_time FROM public.legal_firm_appointments a
  WHERE public.legal_has_sales_role() AND a.firm_id = p_firm_id AND a.status <> 'cancelled'
    AND a.appointment_date IS NOT NULL AND a.appointment_time IS NOT NULL;
$function$;

CREATE OR REPLACE FUNCTION public.legal_sales_queue_city_has_capacity(p_city text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF lower(trim(coalesce(p_city,''))) NOT IN ('sydney','sydney nsw','sydney, nsw','greater sydney') THEN RETURN true; END IF;
 RETURN EXISTS (
   SELECT 1 FROM public.legal_firms f
   WHERE f.is_active AND lower(trim(f.firm_name)) <> 'test family law firm'
     AND (
       EXISTS (SELECT 1 FROM public.legal_firm_locations o WHERE o.firm_id=f.id AND o.is_active
         AND (lower(trim(o.city)) IN ('sydney','sydney nsw','sydney, nsw','greater sydney','bella vista')
           -- Legacy Quill office has its verified Bella Vista address but no city.
           OR (nullif(trim(o.city),'') IS NULL AND o.address ~* ',[[:space:]]*(Sydney|Bella Vista),?[[:space:]]*NSW[[:space:]]+(2000|2153)[[:space:]]*$')))
       OR (NOT EXISTS (SELECT 1 FROM public.legal_firm_locations o WHERE o.firm_id=f.id)
         AND lower(trim(f.city)) IN ('sydney','sydney nsw','sydney, nsw','greater sydney'))
     )
     AND public.legal_get_firm_pack_balance(f.id)>0
 );
END $function$;

CREATE OR REPLACE FUNCTION public.legal_sales_queue_rep(p_session_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE rep uuid;
BEGIN
  IF NOT public.legal_can_access_portal_page('/sales-call') THEN
    RAISE EXCEPTION 'Sales Call access is required';
  END IF;
  SELECT r.id INTO rep FROM public.legal_sales_reps r
    WHERE r.user_id = auth.uid() AND r.is_active AND r.role IN ('admin', 'rep');
  IF rep IS NULL THEN RAISE EXCEPTION 'An active sales caller is required'; END IF;
  PERFORM 1 FROM public.legal_rep_sessions s WHERE s.id = p_session_id
    AND s.rep_id = rep AND s.ended_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Start a calling session first'; END IF;
  RETURN rep;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_save_firm_call_sheet(p_application_id uuid, p_patch jsonb)
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  INSERT INTO public.legal_firm_application_call_sheets(application_id, answers)
  VALUES (p_application_id, p_patch)
  ON CONFLICT (application_id) DO UPDATE SET
    answers = legal_firm_application_call_sheets.answers || EXCLUDED.answers, updated_at = now();
$function$;

CREATE OR REPLACE FUNCTION public.legal_save_firm_offer(_id uuid, _version integer, _snapshot jsonb, _token_hash text DEFAULT NULL::text, _expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare current_row public.legal_firm_offers; begin
 select * into current_row from legal_firm_offers where id=_id for update;
 if not found or current_row.version<>_version then return false; end if;
 if _snapshot->>'id'<>_id::text or (_snapshot->>'revision')::int<>current_row.revision or _snapshot->'draft'->>'applicationId'<>current_row.application_id::text then raise exception 'Offer identity is immutable'; end if;
 if current_row.snapshot->>'proposal'<>'draft' and
   (_snapshot->'draft' is distinct from current_row.snapshot->'draft' or _snapshot->'company' is distinct from current_row.snapshot->'company' or _snapshot->>'templateDigest' is distinct from current_row.snapshot->>'templateDigest') then raise exception 'Create a new revision to change commercial terms'; end if;
 if current_row.snapshot->>'envelopeId' is not null and
   (_snapshot->'details' is distinct from current_row.snapshot->'details' or _snapshot->>'documentDigest' is distinct from current_row.snapshot->>'documentDigest') then raise exception 'Signing content is frozen'; end if;
 update legal_firm_offers set snapshot=jsonb_set(_snapshot,'{version}',to_jsonb(_version+1)),version=_version+1,
 token_hash=coalesce(_token_hash,token_hash),expires_at=coalesce(_expires_at,expires_at),
 revoked_at=case when _snapshot->>'proposal' in ('withdrawn','revision_requested','declined') then now() else revoked_at end where id=_id;
 return true;
end $function$;

CREATE OR REPLACE FUNCTION public.legal_save_firm_reminder_settings(p_firm_id uuid, p_mode text, p_timezone text, p_time time without time zone, p_email text, p_days integer[], p_closures date[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=p_timezone) THEN RAISE EXCEPTION 'Invalid timezone'; END IF;
  UPDATE legal_firm_reminder_settings SET confirmation_enabled_at=CASE WHEN p_mode='confirmation' AND mode<>'confirmation' THEN now() ELSE confirmation_enabled_at END,
    mode=p_mode,timezone=p_timezone,reminder_time=p_time,alert_email=p_email,staffed_days=p_days,closure_dates=p_closures,updated_at=now() WHERE firm_id=p_firm_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Firm not found'; END IF;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_save_firm_schedule(p_firm uuid, p_version text, p_command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE snapshot jsonb; item jsonb; day date; first_day date; dates jsonb; action text; starts time; finishes time;
 duration integer; buffer integer; block public.legal_firm_blocked_slots; cfg jsonb; old public.legal_firm_availability;
BEGIN
 IF NOT (coalesce(auth.role(),'')='service_role' OR coalesce(public.legal_current_firm_id()=p_firm,false) OR coalesce(public.legal_is_admin_user(),false)) THEN RAISE EXCEPTION 'Only this firm or an administrator can edit its calendar'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_firm::text,0));
 snapshot:=public.legal_firm_schedule_snapshot(p_firm);
 IF snapshot IS NULL THEN RAISE EXCEPTION 'Firm not found'; END IF;
 IF md5(snapshot::text) IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'This calendar changed while you were editing. Refresh and try again.'; END IF;
 action:=p_command->>'action';
 IF action='settings' THEN
   duration:=(p_command->>'consultation_minutes')::integer; buffer:=(p_command->>'buffer_minutes')::integer;
   IF duration IS NULL OR buffer IS NULL OR duration NOT BETWEEN 5 AND 240 OR buffer NOT BETWEEN 0 AND 180 THEN RAISE EXCEPTION 'Choose valid consultation and buffer lengths'; END IF;
   UPDATE public.legal_firms SET consultation_duration_minutes=duration,buffer_minutes=buffer WHERE id=p_firm;
   cfg:=p_command;
   IF coalesce((p_command->>'apply_to_existing')::boolean,false) THEN PERFORM set_config('app.confirmed_hours_firm',p_firm::text,true); END IF;
   IF cfg ? 'trading' THEN
     IF jsonb_typeof(cfg->'trading') IS DISTINCT FROM 'array' OR jsonb_array_length(cfg->'trading')<>7 OR (SELECT count(DISTINCT (value->>'day_of_week')::integer) FROM jsonb_array_elements(cfg->'trading'))<>7 THEN RAISE EXCEPTION 'Set operating hours for all seven days'; END IF;
     FOR item IN SELECT * FROM jsonb_array_elements(cfg->'trading') LOOP
       IF (item->>'day_of_week')::integer NOT BETWEEN 0 AND 6 OR item->>'day_of_week' IS NULL OR item->>'is_closed' IS NULL THEN RAISE EXCEPTION 'Invalid operating day'; END IF;
       starts:=(item->>'open_time')::time; finishes:=(item->>'close_time')::time;
       IF starts IS NULL OR finishes IS NULL OR (NOT (item->>'is_closed')::boolean AND starts>=finishes) THEN RAISE EXCEPTION 'Choose an end time after the start time'; END IF;
       INSERT INTO public.legal_firm_trading_hours(firm_id,day_of_week,open_time,close_time,is_open,consult_duration_mins)
       VALUES(p_firm,(item->>'day_of_week')::integer,starts,finishes,NOT (item->>'is_closed')::boolean,coalesce((item->>'consult_duration_mins')::integer,60))
       ON CONFLICT(firm_id,day_of_week) DO UPDATE SET open_time=excluded.open_time,close_time=excluded.close_time,is_open=excluded.is_open
       WHERE (legal_firm_trading_hours.open_time,legal_firm_trading_hours.close_time,legal_firm_trading_hours.is_open) IS DISTINCT FROM (excluded.open_time,excluded.close_time,excluded.is_open);
     END LOOP;
   END IF;
   IF coalesce((p_command->>'apply_to_existing')::boolean,false) THEN
     PERFORM set_config('app.confirmed_duration_firm',p_firm::text,true);
     UPDATE public.legal_firm_appointments SET consultation_duration_minutes=duration WHERE firm_id=p_firm AND appointment_date >= (now() AT TIME ZONE 'Australia/Sydney')::date AND status<>'cancelled' AND disqualified_at IS NULL AND outcome IS DISTINCT FROM 'disqualified' AND consultation_duration_minutes IS DISTINCT FROM duration;
     PERFORM set_config('app.confirmed_duration_firm','',true);
     SET CONSTRAINTS protect_booked_hours IMMEDIATE;
     SET CONSTRAINTS protect_booked_hours DEFERRED;
     PERFORM set_config('app.confirmed_hours_firm','',true);
   END IF;
 ELSIF action IN ('block','hours') THEN
   dates:=p_command->'dates';
   IF jsonb_typeof(dates) IS DISTINCT FROM 'array' OR jsonb_array_length(dates) NOT BETWEEN 1 AND 366 THEN RAISE EXCEPTION 'Choose valid dates'; END IF;
   first_day:=(dates->>0)::date;
   starts:=(p_command->>'start')::time; finishes:=(p_command->>'end')::time;
   IF NOT (action='hours' AND coalesce((p_command->>'closed')::boolean,false)) AND (starts IS NULL OR finishes IS NULL OR starts>=finishes) THEN RAISE EXCEPTION 'Choose an end time after the start time'; END IF;
   IF action='block' AND p_command->>'source_date' IS NOT NULL AND p_command->>'id' IS NULL THEN RAISE EXCEPTION 'This block has changed. Refresh and try again.'; END IF;
   IF action='block' AND p_command->>'id' IS NOT NULL THEN
     SELECT * INTO block FROM public.legal_firm_blocked_slots WHERE id=(p_command->>'id')::uuid AND firm_id=p_firm;
     IF NOT FOUND THEN RAISE EXCEPTION 'This block has changed. Refresh and try again.'; END IF;
     IF p_command->>'source_date' IS NOT NULL AND (jsonb_array_length(dates)<>1 OR p_command->>'scope'='series' OR NOT public.legal_schedule_block_matches(block,(p_command->>'source_date')::date)) THEN RAISE EXCEPTION 'This block has changed. Refresh and try again.'; END IF;
     IF block.is_recurring AND p_command->>'scope'='series' THEN
       UPDATE public.legal_firm_blocked_slots SET start_time=starts,end_time=finishes WHERE id=block.id;
       SET CONSTRAINTS protect_booked_blocks IMMEDIATE;
       RETURN public.legal_get_firm_schedule(p_firm);
     ELSIF block.is_recurring THEN
       UPDATE public.legal_firm_blocked_slots SET excluded_dates=ARRAY(SELECT DISTINCT d FROM unnest(excluded_dates||CASE WHEN p_command->>'source_date' IS NOT NULL THEN ARRAY[(p_command->>'source_date')::date] ELSE ARRAY(SELECT value::date FROM jsonb_array_elements_text(dates)) END) AS d) WHERE id=block.id;
     ELSE DELETE FROM public.legal_firm_blocked_slots WHERE id=block.id; END IF;
   END IF;
   FOR item IN SELECT * FROM jsonb_array_elements(dates) LOOP
     day:=(item#>>'{}')::date;
     IF day IS NULL OR first_day IS NULL OR day>first_day+365 OR day<first_day THEN RAISE EXCEPTION 'Choose dates within the next year'; END IF;
     IF action='block' THEN
       INSERT INTO public.legal_firm_blocked_slots(firm_id,date,start_time,end_time,is_recurring,recur_day_of_week)
       VALUES(p_firm,day,starts,finishes,false,null);
     ELSE
       SELECT * INTO old FROM public.legal_firm_availability WHERE firm_id=p_firm AND override_date=day;
       IF day<>first_day AND (old.override_type IN ('blocked','closed') OR (coalesce(old.override_type,'')<>'open' AND EXISTS(SELECT 1 FROM public.legal_firm_public_holidays h JOIN public.legal_firms c ON c.id=p_firm WHERE h.state=public.legal_schedule_state(c.state) AND h.holiday_date=day))) THEN CONTINUE; END IF;
       INSERT INTO public.legal_firm_availability(firm_id,override_date,override_type,start_time,end_time)
       VALUES(p_firm,day,CASE WHEN (p_command->>'closed')::boolean THEN 'closed' ELSE 'open' END,
         CASE WHEN (p_command->>'closed')::boolean THEN null ELSE starts END,CASE WHEN (p_command->>'closed')::boolean THEN null ELSE finishes END)
       ON CONFLICT(firm_id,override_date) DO UPDATE SET override_type=excluded.override_type,start_time=excluded.start_time,end_time=excluded.end_time;
     END IF;
   END LOOP;
 ELSIF action='unblock' THEN
   SELECT * INTO block FROM public.legal_firm_blocked_slots WHERE id=(p_command->>'id')::uuid AND firm_id=p_firm;
   IF NOT FOUND THEN RAISE EXCEPTION 'This block has changed. Refresh and try again.'; END IF;
   IF block.is_recurring AND p_command->>'scope'='date' THEN
     IF p_command->>'date' IS NULL THEN RAISE EXCEPTION 'Choose a valid date'; END IF;
     UPDATE public.legal_firm_blocked_slots SET excluded_dates=ARRAY(SELECT DISTINCT d FROM unnest(excluded_dates||ARRAY[(p_command->>'date')::date]) d) WHERE id=block.id;
   ELSE DELETE FROM public.legal_firm_blocked_slots WHERE id=block.id; END IF;
 ELSIF action='restore' THEN
   cfg:=p_command->'configuration';
   IF jsonb_typeof(cfg->'blocks') IS DISTINCT FROM 'array' OR jsonb_typeof(cfg->'overrides') IS DISTINCT FROM 'array' OR jsonb_array_length(cfg->'blocks')>5000 OR jsonb_array_length(cfg->'overrides')>5000 THEN RAISE EXCEPTION 'Invalid undo data'; END IF;
   UPDATE public.legal_firms SET consultation_duration_minutes=(cfg->>'consultation_minutes')::integer,buffer_minutes=(cfg->>'buffer_minutes')::integer WHERE id=p_firm;

   IF cfg ? 'trading' THEN
     IF jsonb_typeof(cfg->'trading') IS DISTINCT FROM 'array' OR jsonb_array_length(cfg->'trading')<>7 OR (SELECT count(DISTINCT (value->>'day_of_week')::integer) FROM jsonb_array_elements(cfg->'trading'))<>7 THEN RAISE EXCEPTION 'Set operating hours for all seven days'; END IF;
     FOR item IN SELECT * FROM jsonb_array_elements(cfg->'trading') LOOP
       IF (item->>'day_of_week')::integer NOT BETWEEN 0 AND 6 OR item->>'day_of_week' IS NULL OR item->>'is_closed' IS NULL THEN RAISE EXCEPTION 'Invalid operating day'; END IF;
       starts:=(item->>'open_time')::time; finishes:=(item->>'close_time')::time;
       IF starts IS NULL OR finishes IS NULL OR (NOT (item->>'is_closed')::boolean AND starts>=finishes) THEN RAISE EXCEPTION 'Choose an end time after the start time'; END IF;
       INSERT INTO public.legal_firm_trading_hours(firm_id,day_of_week,open_time,close_time,is_open,consult_duration_mins)
       VALUES(p_firm,(item->>'day_of_week')::integer,starts,finishes,NOT (item->>'is_closed')::boolean,coalesce((item->>'consult_duration_mins')::integer,60))
       ON CONFLICT(firm_id,day_of_week) DO UPDATE SET open_time=excluded.open_time,close_time=excluded.close_time,is_open=excluded.is_open
       WHERE (legal_firm_trading_hours.open_time,legal_firm_trading_hours.close_time,legal_firm_trading_hours.is_open) IS DISTINCT FROM (excluded.open_time,excluded.close_time,excluded.is_open);
     END LOOP;
   END IF;
   DELETE FROM public.legal_firm_blocked_slots WHERE firm_id=p_firm AND id NOT IN (SELECT (value->>'id')::uuid FROM jsonb_array_elements(cfg->'blocks'));
   FOR item IN SELECT * FROM jsonb_array_elements(cfg->'blocks') LOOP
     INSERT INTO public.legal_firm_blocked_slots(id,firm_id,date,start_time,end_time,is_recurring,recur_day_of_week,recur_pattern,recur_days_of_week,recur_day_of_month,recur_nth_week,recur_until,excluded_dates)
     VALUES((item->>'id')::uuid,p_firm,(item->>'date')::date,(item->>'start_time')::time,(item->>'end_time')::time,(item->>'is_recurring')::boolean,(item->>'recur_day_of_week')::integer,item->>'recur_pattern',
       ARRAY(SELECT value::integer FROM jsonb_array_elements_text(coalesce(nullif(item->'recur_days_of_week','null'::jsonb),'[]'))),(item->>'recur_day_of_month')::integer,(item->>'recur_nth_week')::integer,(item->>'recur_until')::date,
       ARRAY(SELECT value::date FROM jsonb_array_elements_text(coalesce(nullif(item->'excluded_dates','null'::jsonb),'[]'))))
     ON CONFLICT(id) DO UPDATE SET date=excluded.date,start_time=excluded.start_time,end_time=excluded.end_time,is_recurring=excluded.is_recurring,recur_day_of_week=excluded.recur_day_of_week,recur_pattern=excluded.recur_pattern,
       recur_days_of_week=excluded.recur_days_of_week,recur_day_of_month=excluded.recur_day_of_month,recur_nth_week=excluded.recur_nth_week,recur_until=excluded.recur_until,excluded_dates=excluded.excluded_dates
     WHERE legal_firm_blocked_slots.firm_id=p_firm AND (to_jsonb(legal_firm_blocked_slots)-'created_at') IS DISTINCT FROM (to_jsonb(excluded)-'created_at');
     IF NOT EXISTS(SELECT 1 FROM public.legal_firm_blocked_slots WHERE id=(item->>'id')::uuid AND firm_id=p_firm) THEN RAISE EXCEPTION 'Invalid block reference'; END IF;
   END LOOP;
   DELETE FROM public.legal_firm_availability WHERE firm_id=p_firm AND override_date NOT IN (SELECT (value->>'override_date')::date FROM jsonb_array_elements(cfg->'overrides'));
   FOR item IN SELECT * FROM jsonb_array_elements(cfg->'overrides') LOOP
     INSERT INTO public.legal_firm_availability(firm_id,override_date,override_type,start_time,end_time)
     VALUES(p_firm,(item->>'override_date')::date,item->>'override_type',(item->>'start_time')::time,(item->>'end_time')::time)
     ON CONFLICT(firm_id,override_date) DO UPDATE SET override_type=excluded.override_type,start_time=excluded.start_time,end_time=excluded.end_time
     WHERE (legal_firm_availability.override_type,legal_firm_availability.start_time,legal_firm_availability.end_time) IS DISTINCT FROM (excluded.override_type,excluded.start_time,excluded.end_time);
   END LOOP;
 ELSE RAISE EXCEPTION 'Unknown calendar action'; END IF;
 SET CONSTRAINTS protect_booked_blocks,protect_booked_hours,protect_booked_overrides IMMEDIATE;
 RETURN public.legal_get_firm_schedule(p_firm);
END $function$;

CREATE OR REPLACE FUNCTION public.legal_schedule_block_matches(b legal_firm_blocked_slots, p_day date)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
 SELECT CASE WHEN NOT coalesce(b.is_recurring,false) THEN b.date=p_day ELSE
 NOT (p_day=ANY(coalesce(b.excluded_dates,'{}'))) AND (b.date IS NULL OR p_day>=b.date)
 AND (b.recur_until IS NULL OR p_day<=b.recur_until)
 AND CASE coalesce(b.recur_pattern,'weekly')
 WHEN 'daily' THEN true
 WHEN 'weekly' THEN ((extract(dow FROM p_day)::integer)=ANY(CASE WHEN cardinality(b.recur_days_of_week)>0 THEN b.recur_days_of_week ELSE ARRAY[b.recur_day_of_week] END))
 WHEN 'monthly_date' THEN extract(day FROM p_day)::integer=b.recur_day_of_month
 WHEN 'monthly_nth_dow' THEN extract(dow FROM p_day)::integer=b.recur_day_of_week
   AND CASE WHEN b.recur_nth_week=5 THEN extract(month FROM p_day+7)<>extract(month FROM p_day)
     ELSE ((extract(day FROM p_day)::integer-1)/7)+1=b.recur_nth_week END
 ELSE false END END
$function$;

CREATE OR REPLACE FUNCTION public.legal_schedule_hours(p_firm uuid, p_day date)
 RETURNS TABLE(opens integer, closes integer, step integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE t public.legal_firm_trading_hours; o public.legal_firm_availability; st text;
BEGIN
 SELECT * INTO t FROM public.legal_firm_trading_hours WHERE firm_id=p_firm AND day_of_week=extract(dow FROM p_day)::integer;
 SELECT * INTO o FROM public.legal_firm_availability WHERE firm_id=p_firm AND override_date=p_day;
 IF o.override_type IN ('blocked','closed') THEN RETURN; END IF;
 IF o.override_type='open' AND o.start_time IS NOT NULL AND o.end_time IS NOT NULL THEN
   RETURN QUERY SELECT public.legal_schedule_minute(o.start_time::text),public.legal_schedule_minute(o.end_time::text),coalesce(t.consult_duration_mins,60); RETURN;
 END IF;
 SELECT public.legal_schedule_state(state) INTO st FROM public.legal_firms WHERE id=p_firm;
 IF EXISTS(SELECT 1 FROM public.legal_firm_public_holidays WHERE state=st AND holiday_date=p_day) THEN RETURN; END IF;
 IF t.id IS NULL OR NOT t.is_open THEN RETURN; END IF;
 RETURN QUERY SELECT public.legal_schedule_minute(t.open_time::text),public.legal_schedule_minute(t.close_time::text),coalesce(t.consult_duration_mins,60);
END $function$;

CREATE OR REPLACE FUNCTION public.legal_schedule_minute(p_time text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
 SELECT (extract(epoch FROM p_time::time)/60)::integer
$function$;

CREATE OR REPLACE FUNCTION public.legal_schedule_state(p_state text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
 SELECT CASE upper(btrim(p_state)) WHEN 'NEW SOUTH WALES' THEN 'NSW' WHEN 'VICTORIA' THEN 'VIC'
 WHEN 'QUEENSLAND' THEN 'QLD' WHEN 'SOUTH AUSTRALIA' THEN 'SA' WHEN 'WESTERN AUSTRALIA' THEN 'WA'
 WHEN 'TASMANIA' THEN 'TAS' WHEN 'NORTHERN TERRITORY' THEN 'NT' WHEN 'AUSTRALIAN CAPITAL TERRITORY' THEN 'ACT'
 ELSE upper(btrim(p_state)) END
$function$;

CREATE OR REPLACE FUNCTION public.legal_set_legal_booking_target(p_rep uuid, p_month text, p_target integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service only'; END IF;
 IF p_month IS NULL OR p_month !~ '^\d{4}-(0[1-9]|1[0-2])$' OR p_target IS NULL OR p_target NOT BETWEEN 0 AND 100000 OR NOT EXISTS(SELECT 1 FROM legal_sales_reps WHERE id=p_rep) THEN RAISE EXCEPTION 'Invalid target'; END IF;
 INSERT INTO legal_app_settings(key,value) VALUES('booking_targets:'||p_month,jsonb_build_object(p_rep::text,p_target))
 ON CONFLICT(key) DO UPDATE SET value=coalesce(legal_app_settings.value,'{}'::jsonb)||excluded.value;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_set_staff_portal_pages(p_rep_id uuid, p_pages text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.legal_is_admin_user() THEN RAISE EXCEPTION 'Admins only'; END IF;
  IF p_pages IS NULL THEN RAISE EXCEPTION 'Choose the allowed tabs'; END IF;
  UPDATE public.legal_sales_reps SET portal_pages = p_pages WHERE id = p_rep_id AND role <> 'admin';
  IF NOT FOUND THEN RAISE EXCEPTION 'Staff member not found or is an admin'; END IF;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_set_up_firm_portal(p_application_id uuid)
 RETURNS TABLE(firm_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  app public.legal_firm_applications%ROWTYPE;
  target_id uuid;
  candidates uuid[];
  clean_name text;
  contact_name text;
BEGIN
  IF NOT coalesce(public.legal_is_admin_user(), false)
     OR NOT coalesce(public.legal_can_manage_firm_pipeline(), false) THEN
    RAISE EXCEPTION 'Only admins with Firm Pipeline access can set up a firm portal.' USING ERRCODE = '42501';
  END IF;

  -- Serialize setup across applications too: duplicate leads must not create
  -- two firms when separate staff members set them up at the same time.
  PERFORM pg_advisory_xact_lock(611100100);
  SELECT * INTO app FROM public.legal_firm_applications WHERE id = p_application_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Firm application not found.'; END IF;

  SELECT link.firm_id INTO target_id FROM public.legal_firm_pipeline_portals link
    WHERE link.application_id = app.id;
  IF target_id IS NOT NULL THEN RETURN QUERY SELECT target_id, false; RETURN; END IF;

  clean_name := nullif(btrim(app.firm_name), '');
  IF clean_name IS NULL THEN
    RAISE EXCEPTION 'Add a firm name in the pipeline before setting up the portal.';
  END IF;
  contact_name := nullif(btrim(concat_ws(' ', nullif(btrim(app.first_name), ''), nullif(btrim(app.last_name), ''))), '');

  -- Include inactive firms. Conflicting matches need review, never an arbitrary
  -- choice or a duplicate account. Keep all existing portal details intact.
  SELECT array_agg(f.id) INTO candidates FROM public.legal_firms f
  WHERE lower(regexp_replace(btrim(f.firm_name), '\s+', ' ', 'g')) = lower(regexp_replace(clean_name, '\s+', ' ', 'g'))
     OR (nullif(btrim(app.email), '') IS NOT NULL AND lower(btrim(f.email)) = lower(btrim(app.email)));
  IF cardinality(candidates) > 1 THEN
    RAISE EXCEPTION 'Multiple portal firms match this name or email. Review the existing firms in the firm portal before trying again.';
  END IF;
  target_id := candidates[1];

  IF target_id IS NULL THEN
    INSERT INTO public.legal_firms(firm_name, email, phone, city, notes)
    VALUES (clean_name, nullif(btrim(app.email), ''), nullif(btrim(app.phone), ''), nullif(btrim(app.city), ''),
      CASE WHEN contact_name IS NOT NULL THEN 'Primary contact: ' || contact_name END)
    RETURNING id INTO target_id;
    created := true;
  ELSE
    -- Fill gaps only; setup must not overwrite details already maintained here.
    UPDATE public.legal_firms f SET
      email = coalesce(nullif(btrim(f.email), ''), nullif(btrim(app.email), '')),
      phone = coalesce(nullif(btrim(f.phone), ''), nullif(btrim(app.phone), '')),
      city = coalesce(nullif(btrim(f.city), ''), nullif(btrim(app.city), '')),
      notes = CASE WHEN contact_name IS NOT NULL
        AND position('Primary contact: ' || contact_name IN coalesce(f.notes, '')) = 0 THEN
        concat_ws(E'\n\n', nullif(btrim(f.notes), ''), 'Primary contact: ' || contact_name)
        ELSE f.notes END
    WHERE f.id = target_id;
    created := false;
  END IF;

  INSERT INTO public.legal_firm_pipeline_portals(application_id, firm_id) VALUES (app.id, target_id);
  INSERT INTO public.legal_firm_application_notes(application_id, body, kind)
    VALUES (app.id, CASE WHEN created THEN 'Set up in firm portal: ' ELSE 'Linked to existing firm portal: ' END || clean_name, 'system');
  RETURN QUERY SELECT target_id, created;
END;
$function$;

CREATE OR REPLACE FUNCTION public.legal_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $function$;

CREATE OR REPLACE FUNCTION public.legal_staff_portal_pages(p_rep_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.legal_sales_reps; cold jsonb; pages text[];
BEGIN
  SELECT * INTO r FROM public.legal_sales_reps WHERE id = p_rep_id;
  IF NOT FOUND THEN RETURN ARRAY[]::text[]; END IF;
  IF r.role = 'admin' THEN RETURN ARRAY['/dashboard','/leads','/sales-call','/training',
    '/booked-appointments','/inbox','/leaderboard','/pitch-deck','/firm-cold-calling','/firms','/firm-portal']; END IF;
  IF r.portal_pages IS NOT NULL THEN RETURN r.portal_pages; END IF;
  IF r.sales_only THEN RETURN ARRAY['/sales-call','/inbox']; END IF;
  SELECT value INTO cold FROM public.legal_app_settings WHERE key = 'cold_calling';
  IF coalesce(cold->'setter_user_ids', '[]'::jsonb) ? r.user_id::text THEN
    SELECT array_agg(DISTINCT p) INTO pages FROM (
      SELECT '/firm-cold-calling' AS p UNION ALL
      SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(cold->'setter_allowed_pages') = 'array'
        THEN cold->'setter_allowed_pages' ELSE '[]'::jsonb END)
    ) allowed WHERE p = ANY(ARRAY['/dashboard','/leads','/sales-call','/training','/booked-appointments',
      '/inbox','/leaderboard','/pitch-deck','/firm-cold-calling','/firms','/firm-portal']);
    RETURN pages;
  END IF;
  pages := ARRAY['/dashboard','/sales-call','/booked-appointments','/inbox','/leaderboard','/pitch-deck','/firm-portal'];
  IF EXISTS(SELECT 1 FROM public.legal_app_settings WHERE key = 'training' AND value->'reps_can_see' = 'true'::jsonb)
    THEN pages := array_append(pages, '/training'); END IF;
  RETURN pages;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_stamp_client_asset_calculation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.lead_id IS DISTINCT FROM OLD.lead_id OR NEW.revision <> OLD.revision + 1 THEN
      RAISE EXCEPTION 'Asset calculation must stay on its client and increment its revision';
    END IF;
  ELSIF NEW.revision <> 1 THEN
    RAISE EXCEPTION 'Asset calculation must start at revision 1';
  END IF;
  NEW.updated_at := now();
  NEW.updated_by := auth.uid();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.legal_stop_firm_booking_follow_ups()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'legal_sms_messages' THEN
    IF NEW.direction = 'inbound' AND length(regexp_replace(coalesce(NEW.phone,''), '\D', '', 'g')) >= 9 THEN
      UPDATE public.legal_firm_booking_follow_ups q SET status = 'cancelled', last_error = 'Recipient replied'
      FROM public.legal_firm_applications a
      WHERE a.id = q.application_id AND q.status IN ('pending', 'checking')
        AND right(regexp_replace(coalesce(a.phone,''), '\D', '', 'g'),9)
          = right(regexp_replace(NEW.phone, '\D', '', 'g'),9);
    END IF;
  ELSIF NEW.stage NOT IN ('new', 'no_answer') THEN
    UPDATE public.legal_firm_booking_follow_ups SET status = 'cancelled', last_error = 'Application progressed or closed'
    WHERE application_id = NEW.id AND status IN ('pending','checking');
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_stop_firm_text_sequence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ BEGIN UPDATE public.legal_firm_booking_follow_ups SET status='cancelled',last_error='Firm conversation started' WHERE application_id=NEW.application_id AND status IN ('pending','checking'); RETURN NEW; END $function$;

CREATE OR REPLACE FUNCTION public.legal_sync_firm_calendly_booking(p_application_id uuid, p_expected_email text, p_expected_stage text, p_checked_at timestamp with time zone, p_event_uri text, p_start_at timestamp with time zone, p_end_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  app public.legal_firm_applications%ROWTYPE;
  activity text;
BEGIN
  IF p_checked_at IS NULL THEN RAISE EXCEPTION 'Check time is required'; END IF;
  IF p_event_uri IS NOT NULL AND (
    p_event_uri !~ '^https://api[.]calendly[.]com/scheduled_events/[a-zA-Z0-9-]+$'
    OR p_start_at IS NULL OR p_end_at IS NULL OR p_end_at <= p_start_at
    OR p_start_at < p_checked_at
  ) THEN RAISE EXCEPTION 'Invalid Calendly booking'; END IF;
  IF p_event_uri IS NULL AND (p_start_at IS NOT NULL OR p_end_at IS NOT NULL) THEN
    RAISE EXCEPTION 'Incomplete Calendly booking';
  END IF;
  SELECT * INTO app FROM public.legal_firm_applications WHERE id = p_application_id FOR UPDATE;
  IF NOT FOUND OR coalesce(app.calendly_booking_email, app.email) IS DISTINCT FROM p_expected_email
    OR app.stage IS DISTINCT FROM p_expected_stage
    OR app.stage NOT IN ('new','no_answer','follow_up','calendly_booked')
    OR app.calendly_checked_at >= p_checked_at
    OR app.calendly_sync_attempted_at > p_checked_at THEN RETURN 'stale'; END IF;
  IF p_event_uri IS NOT NULL THEN
    IF app.calendly_event_uri IS DISTINCT FROM p_event_uri
      OR app.calendly_start_at IS DISTINCT FROM p_start_at
      OR app.stage <> 'calendly_booked' THEN
      activity := 'Calendly booked with Peter for '
        || to_char(p_start_at AT TIME ZONE 'Australia/Sydney', 'FMDD Mon YYYY FMHH12:MI AM')
        || ' (Sydney time). Already scheduled; no booking call needed.';
    END IF;
    UPDATE public.legal_firm_applications SET stage = 'calendly_booked',
      calendly_event_uri = p_event_uri, calendly_start_at = p_start_at,
      calendly_end_at = p_end_at, calendly_checked_at = p_checked_at
    WHERE id = app.id;
  ELSIF app.stage = 'calendly_booked' AND app.calendly_start_at > p_checked_at THEN
    activity := 'Calendly booking cancelled. Moved to Follow ups to arrange another time.';
    UPDATE public.legal_firm_applications SET stage = 'follow_up',
      calendly_event_uri = NULL, calendly_start_at = NULL, calendly_end_at = NULL,
      calendly_checked_at = p_checked_at WHERE id = app.id;
  ELSE
    UPDATE public.legal_firm_applications SET calendly_checked_at = p_checked_at WHERE id = app.id;
  END IF;
  IF activity IS NOT NULL THEN
    INSERT INTO public.legal_firm_application_notes(application_id, body, kind)
      VALUES(app.id, activity, 'system');
    RETURN 'updated';
  END IF;
  RETURN 'checked';
END $function$;

CREATE OR REPLACE FUNCTION public.legal_track_appointment_reminder_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP='INSERT' THEN
    INSERT INTO legal_appointment_attendance(appointment_id) VALUES(NEW.id);
  ELSIF ROW(NEW.appointment_date,NEW.appointment_time,NEW.firm_id,NEW.lawyer_id,NEW.lead_id,NEW.client_phone,NEW.consult_mode,NEW.location_id)
    IS DISTINCT FROM ROW(OLD.appointment_date,OLD.appointment_time,OLD.firm_id,OLD.lawyer_id,OLD.lead_id,OLD.client_phone,OLD.consult_mode,OLD.location_id)
    OR (NEW.status='booked' AND OLD.status<>'booked') THEN
    INSERT INTO legal_appointment_attendance_events(appointment_id,booking_version,kind,detail)
      SELECT appointment_id,booking_version,'rescheduled','Confirmation reset for changed appointment details' FROM legal_appointment_attendance WHERE appointment_id=NEW.id;
    UPDATE legal_appointment_attendance SET booking_version=gen_random_uuid(),booking_changed_at=now(),status='unrequested',
      confirmed_at=NULL,latest_reply=NULL,latest_reply_at=NULL,call_outcome=NULL,called_at=NULL,reason=NULL WHERE appointment_id=NEW.id;
    UPDATE legal_appointment_reminder_jobs SET state='cancelled',last_error='Appointment changed' WHERE appointment_id=NEW.id AND state='pending';
  END IF;
  IF NEW.status<>'booked' OR NEW.outcome IS NOT NULL THEN
    UPDATE legal_appointment_reminder_jobs SET state='cancelled',last_error='Appointment no longer active' WHERE appointment_id=NEW.id AND state='pending';
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.legal_update_firm_sms_status(p_id uuid, p_sid text, p_status text, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ UPDATE public.legal_firm_application_messages SET twilio_sid=p_sid,status=p_status,error_code=p_error WHERE direction='outbound' AND (id=p_id OR twilio_sid=p_sid) AND (twilio_sid IS NULL OR twilio_sid=p_sid) AND status NOT IN ('delivered','failed','undelivered') AND (CASE p_status WHEN 'delivered' THEN 4 WHEN 'failed' THEN 4 WHEN 'undelivered' THEN 4 WHEN 'sent' THEN 3 WHEN 'sending' THEN 2 WHEN 'queued' THEN 1 ELSE 0 END >= CASE status WHEN 'sent' THEN 3 WHEN 'queued' THEN 1 ELSE 0 END); $function$;

