-- Indexes
CREATE UNIQUE INDEX "legal_ad_briefing_one_callback" ON public.legal_ad_briefing_calls USING btree (retry_of) WHERE (retry_of IS NOT NULL);
CREATE UNIQUE INDEX "legal_ad_briefing_one_daily_call" ON public.legal_ad_briefing_calls USING btree (owner_id, call_date) WHERE ((kind = 'daily'::text) AND (retry_of IS NULL));
CREATE UNIQUE INDEX "legal_ad_briefing_one_test_per_revision" ON public.legal_ad_briefing_calls USING btree (owner_id, call_date, COALESCE(test_revision, 'legacy'::text)) WHERE (kind = 'test'::text);
CREATE UNIQUE INDEX "legal_ad_briefing_unique_voice_conversation" ON public.legal_ad_briefing_calls USING btree (elevenlabs_conversation_id) WHERE (elevenlabs_conversation_id IS NOT NULL);
CREATE UNIQUE INDEX "legal_ad_spend_meta_identity" ON public.legal_ad_spend_daily USING btree (account_id, ad_id, date) WHERE (source = 'meta'::text);
CREATE INDEX "legal_appointment_reminder_due_idx" ON public.legal_appointment_reminder_jobs USING btree (due_at) WHERE (state = 'pending'::text);
CREATE INDEX "legal_appointment_reminder_reply_idx" ON public.legal_appointment_reminder_jobs USING btree (to_phone, from_phone, claimed_at);
CREATE UNIQUE INDEX "legal_appointment_reminder_sid_idx" ON public.legal_appointment_reminder_jobs USING btree (twilio_sid) WHERE (twilio_sid IS NOT NULL);
CREATE INDEX "legal_call_records_queue_attempts" ON public.legal_call_records USING btree (lead_id, created_at DESC);
CREATE INDEX "legal_client_leads_created_idx" ON public.legal_client_leads USING btree (created_at DESC);
CREATE INDEX "legal_client_leads_queue_created" ON public.legal_client_leads USING btree (created_at DESC, id);
CREATE INDEX "legal_client_leads_rep_idx" ON public.legal_client_leads USING btree (rep_id);
CREATE INDEX "legal_client_leads_status_idx" ON public.legal_client_leads USING btree (status);
CREATE INDEX "legal_cold_calling_audit_firm_idx" ON public.legal_cold_calling_audit_log USING btree (prospect_firm_id, at DESC);
CREATE UNIQUE INDEX "legal_daily_phone_assignments_caller_day_idx" ON public.legal_daily_phone_assignments USING btree (work_date, caller_user_id);
CREATE INDEX "legal_daily_phone_assignments_number_idx" ON public.legal_daily_phone_assignments USING btree (outbound_caller_id_id, work_date DESC);
CREATE INDEX "legal_firm_application_calls_history" ON public.legal_firm_application_calls USING btree (application_id, created_at DESC);
CREATE INDEX "legal_firm_messages_history" ON public.legal_firm_application_messages USING btree (application_id, created_at DESC);
CREATE INDEX "legal_firm_application_notes_app_idx" ON public.legal_firm_application_notes USING btree (application_id, created_at DESC);
CREATE INDEX "legal_firm_application_phone_lookup" ON public.legal_firm_applications USING btree (legal_firm_phone_key(phone));
CREATE INDEX "legal_firm_applications_calendly_check" ON public.legal_firm_applications USING btree (calendly_sync_attempted_at NULLS FIRST, id) WHERE ((email IS NOT NULL) AND (stage = ANY (ARRAY['new'::text, 'no_answer'::text, 'follow_up'::text, 'calendly_booked'::text])));
