-- Views
CREATE VIEW public.legal_firm_conversation_overview WITH (security_invoker=true) AS
SELECT application_id,
    max(created_at) AS last_activity_at,
    count(*) FILTER (WHERE direction = 'inbound'::text AND reviewed_at IS NULL) AS unread_count,
    (array_agg(preview ORDER BY created_at DESC))[1] AS preview
   FROM ( SELECT legal_firm_application_messages.application_id,
            legal_firm_application_messages.created_at,
            legal_firm_application_messages.direction,
            legal_firm_application_messages.reviewed_at,
            legal_firm_application_messages.body AS preview
           FROM legal_firm_application_messages
        UNION ALL
         SELECT legal_firm_application_calls.application_id,
            legal_firm_application_calls.created_at,
            legal_firm_application_calls.direction,
            legal_firm_application_calls.reviewed_at,
                CASE
                    WHEN legal_firm_application_calls.direction = 'inbound'::text THEN 'Incoming call · '::text
                    ELSE 'Outgoing call · '::text
                END || replace(legal_firm_application_calls.status, '-'::text, ' '::text)
           FROM legal_firm_application_calls) events
  GROUP BY application_id;
REVOKE ALL ON public.legal_firm_conversation_overview FROM anon, authenticated;
GRANT INSERT, SELECT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.legal_firm_conversation_overview TO anon;
GRANT INSERT, SELECT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.legal_firm_conversation_overview TO authenticated;
GRANT INSERT, SELECT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.legal_firm_conversation_overview TO service_role;

